// The runtime of TypeScript parsers generated by zp gen -lang ts.
//
// zp gen writes everything after the "--- Runtime ---" line below, followed by budget.ts, trace.ts
// and profile.ts, as runtime.ts: one module without dependencies that every generated parser imports.
// The parser.ts generated from a grammar holds the expression functions and the statements that set
// up the rule table. Every top-level declaration is exported; parser.ts re-exports the public ones.
// The module mirrors runtime/runtime.go, the runtime of
// generated Go parsers, line for line where it can: the results must equal the engine's exactly, which
// the generator tests in internal/engine check by running the generated code with Node.js.
//
// The code uses only erasable TypeScript syntax (no enums, namespaces or parameter properties), so
// runtimes that strip types can run it directly, and only the ES2020 library (BigInt).

// --- Runtime ---

/**
 * A value of an action, a predicate or a node field: a node, an int, a string, a bool or null. An int
 * is a number, or a bigint when it is outside the safe integer range (ints are 64-bit, as in the
 * engine, and wrap around on overflow).
 */
export type Value = Node | number | bigint | string | boolean | null;

/** The unit of input positions. */
export type Unit = 0 | 1;
/** CodePoints counts Unicode code points. It is the default. */
export const CodePoints: Unit = 0;
/** Bytes counts UTF-8 bytes. */
export const Bytes: Unit = 1;

/** A field of a node: a struct field or a capture. */
export interface NodeField {
  readonly name: string;
  value: Value;
}

export const noNodes: readonly (Node | null)[] = Object.freeze([]);
export const noFields: readonly NodeField[] = Object.freeze([]);

/**
 * The JSON form of a value (Node.toJSON): an object for a node, an error value or a struct, an
 * array for a tuple or list value, and the carried value for any other value.
 */
export type NodeJSON = unknown;

// ValueNodeJSON and ErrorJSON are the JSON forms of a node and of an error value.
export interface ValueNodeJSON {
  type?: string; // a named node type
  start: number;
  end: number;
  value: unknown;
  rule?: string;
  captures?: { [name: string]: unknown };
}

export interface ErrorJSON {
  start: number;
  end: number;
  error: unknown;
  expected?: unknown;
}

// Kinds of the value model that are not nodes. Their names cannot be type names.
export const typeBox = "(box)"; // a value other than a node, carried where a node is expected
export const typeTupleValue = "(tuple)"; // a tuple value: the Value of a tuple node
export const typeListValue = "(list)"; // a list value: the Value of a list node, or a list made by an action

/**
 * A value of a parse result: a node, whose value is a string, a tuple or a list, an error value of
 * recovery, a struct built by an action, or a carrier of another value. In JSON a node is an object
 * with the members start, end and value, and, with source information, rule and captures.
 */
export class Node {
  /** The type name: string, tuple, list or error for the kinds of nodes, or a type of the grammar. */
  type: string;
  /** The name of the rule that produced the node, with source information. */
  rule: string;
  /** The range in the input, in the position unit (end is exclusive). */
  start: number;
  end: number;
  /** The text of a string node. */
  text: string;
  /** The elements of a tuple or list. Omitted elements are null. */
  children: readonly (Node | null)[];
  /** The struct fields and captures, in the order they were set. */
  fields: readonly NodeField[];
  /** @internal The node was made in the rule body being evaluated, which may change it. */
  fresh: boolean;
  /** @internal The node is a terminal. */
  terminal: boolean;
  /** @internal The captures in fields are output (source information). */
  labeled = false;
  /** @internal The value carried by a box. */
  box: Value = null;

  constructor(
    type: string,
    rule: string,
    start: number,
    end: number,
    text: string,
    children: readonly (Node | null)[],
    fields: readonly NodeField[],
    fresh: boolean,
    terminal: boolean,
  ) {
    this.type = type;
    this.rule = rule;
    this.start = start;
    this.end = end;
    this.text = text;
    this.children = children;
    this.fields = fields;
    this.fresh = fresh;
    this.terminal = terminal;
  }

  /** Returns the value of the field name (null if there is none). */
  field(name: string): Value {
    for (const f of this.fields) {
      if (f.name === name) {
        return f.value;
      }
    }
    return null;
  }

  /** Reports whether the node is a terminal. */
  isTerminal(): boolean {
    return this.terminal;
  }

  /**
   * Renders the value as an S-expression of its shape, without positions, as the engine's
   * Node.String does: a string is quoted, a tuple is ( ), a list [ ], null is nil, a struct is
   * Name{Field: value}, and an error is error("message"). A node of a named node type N is written
   * with N before its brackets: N("text"), N( ) and N[ ]. With source information, a node is
   * followed by @rule, a captured element is preceded by name:, and a capture whose value is not an
   * element is written after the elements as &name:value.
   */
  toString(): string {
    return sexpr(this);
  }

  /**
   * Returns the JSON form of the value, which JSON.stringify uses. Ints outside the safe integer
   * range become (inexact) numbers; marshal encodes them exactly.
   */
  toJSON(): NodeJSON {
    const shape = nodeShape(this);
    switch (shape) {
      case shapeBox:
        return typeof this.box === "bigint" ? Number(this.box) : this.box;
      case shapeString:
      case shapeTuple:
      case shapeList: {
        // The keys in the order of the engine's JSON (objects keep the order of insertion). A node
        // of a named node type names its type.
        const o: ValueNodeJSON =
          this instanceof TypedNode
            ? { type: this.type, start: this.start, end: this.end, value: shape === shapeString ? this.text : this.children }
            : { start: this.start, end: this.end, value: shape === shapeString ? this.text : this.children };
        if (this.rule !== "") {
          o.rule = this.rule;
        }
        if (this.labeled && this.fields.length > 0) {
          const caps: { [name: string]: unknown } = Object.create(null);
          for (const c of captureLocations(this)) {
            caps[c.name] = c.side ? { value: typeof c.value === "bigint" ? Number(c.value) : c.value } : { path: c.path };
          }
          o.captures = caps;
        }
        return o;
      }
      case shapeError: {
        const o: ErrorJSON = { start: this.start, end: this.end, error: this.field("message") };
        const expected = lookupField(this, "expected");
        if (expected !== undefined) {
          o.expected = expected;
        }
        return o;
      }
      case shapeTupleValue:
      case shapeListValue:
        return this.children;
    }
    // Without a prototype, a field named __proto__ is a field like the others.
    const fs: { [name: string]: unknown } = Object.create(null);
    for (const f of sortedFields(this.fields)) {
      fs[f.name] = typeof f.value === "bigint" ? Number(f.value) : f.value;
    }
    return { type: this.type, start: this.start, end: this.end, fields: fs };
  }
}

/**
 * A node of a named node type (type T = node[U]): the string, tuple or list node it was converted
 * from, with the type name T.
 */
export class TypedNode extends Node {
  /** @internal The shape of the node it was converted from (shapeString, shapeTuple or shapeList). */
  readonly base: number;

  constructor(type: string, start: number, end: number, text: string, children: readonly (Node | null)[], fields: readonly NodeField[], terminal: boolean, base: number) {
    super(type, "", start, end, text, children, fields, false, terminal);
    this.base = base;
  }
}

// convertNode returns the node of the named node type typ that v converts to: a copy of v with
// the same range and content, or v itself if it already has the type. It returns null if v is not
// a string, tuple or list node.
export function convertNode(typ: string, v: Value): Node | null {
  if (!(v instanceof Node)) {
    return null;
  }
  const shape = nodeShape(v);
  if (shape > shapeList) {
    return null;
  }
  if (v.type === typ) {
    return v;
  }
  // The node keeps what it holds now: the rule that made a fresh node may still change it.
  const n = new TypedNode(typ, v.start, v.end, v.text, v.fresh ? v.children.slice() : v.children, v.fields.slice(), v.terminal, shape);
  n.labeled = v.labeled;
  return n;
}

// Shapes of a Node: what it stands for in the value model.
export const shapeString = 0; // a node whose value is a string (text)
export const shapeTuple = 1; // a node whose value is a tuple (children)
export const shapeList = 2; // a node whose value is a list (children)
export const shapeError = 3; // an error value of recovery
export const shapeBox = 4; // a box carrying a value other than a node
export const shapeTupleValue = 5; // a tuple value (children)
export const shapeListValue = 6; // a list value (children)
export const shapeStruct = 7; // a struct value (fields)

export function nodeShape(n: Node): number {
  switch (n.type) {
    case "string":
      return shapeString;
    case "tuple":
      return shapeTuple;
    case "list":
      return shapeList;
    case "error":
      return shapeError;
    case typeBox:
      return shapeBox;
    case typeTupleValue:
      return shapeTupleValue;
    case typeListValue:
      return shapeListValue;
  }
  if (n instanceof TypedNode) {
    return n.base;
  }
  return n.terminal ? shapeString : shapeStruct;
}

// isValueNode reports whether n is a node of the value model (a string node, a tuple or list node,
// or an error value) rather than a struct, a box or a list or tuple value.
export function isValueNode(n: Node): boolean {
  switch (n.type) {
    case "string":
    case "tuple":
    case "list":
    case "error":
      return true;
  }
  return n.terminal || n instanceof TypedNode;
}

// unboxNode returns the value that the carrier n stands for: the box's value for a box, and n
// otherwise.
export function unboxNode(n: Node | null): Value {
  if (n !== null && n.type === typeBox) {
    return n.box;
  }
  return n;
}

// unboxValue is unboxNode for a value that may be a carrier.
export function unboxValue(v: Value): Value {
  return v instanceof Node ? unboxNode(v) : v;
}

// lookupField returns the value of the field name of n, or undefined if n has none.
export function lookupField(n: Node, name: string): Value | undefined {
  for (const f of n.fields) {
    if (f.name === name) {
      return f.value;
    }
  }
  return undefined;
}

export function sortedFields(fs: readonly NodeField[]): NodeField[] {
  return fs.slice().sort((a, b) => compareStrings(a.name, b.name));
}

export function setField(n: Node, name: string, v: Value, control: BudgetControl | null = null): void {
  if (n.fields === noFields) {
    n.fields = [{ name, value: v }];
    return;
  }
  const fs = n.fields as NodeField[];
  for (const f of fs) {
    control?.charge(1);
    if (control === null ? f.name === name : equalStringsSpend(f.name, name, control)) {
      f.value = v;
      return;
    }
  }
  fs.push({ name, value: v });
}

// CaptureLocation is where a capture of a node is: a path of tuple indexes into the node's value,
// or, for a capture whose value is not an element (one in a positive lookahead), its value.
export interface CaptureLocation {
  name: string;
  path: number[];
  side: boolean;
  value: Value;
}

// captureLocations returns the locations of the captures of the tuple node n, in name order.
export function captureLocations(n: Node): CaptureLocation[] {
  const out: CaptureLocation[] = [];
  for (const f of sortedFields(n.fields)) {
    const v = f.value;
    if (!(v instanceof Node)) {
      if (v !== null) {
        out.push({ name: f.name, path: [], side: true, value: v });
      }
      continue;
    }
    const path = findElement(n, v);
    if (path !== null) {
      out.push({ name: f.name, path, side: false, value: null });
    } else {
      out.push({ name: f.name, path: [], side: true, value: v });
    }
  }
  return out;
}

// findElement returns the path of x among the elements of the tuple node n and of the tuple nodes
// nested in it, breadth first, or null.
export function findElement(n: Node, x: Node): number[] | null {
  const queue: [Node, number[]][] = [[n, []]];
  for (let q = 0; q < queue.length; q++) {
    const [m, path] = queue[q]!;
    for (let i = 0; i < m.children.length; i++) {
      const c = m.children[i]!;
      if (c === null) {
        continue;
      }
      const p = path.concat(i);
      if (c === x) {
        return p;
      }
      if (nodeShape(c) === shapeTuple && c.rule === "") {
        queue.push([c, p]);
      }
    }
  }
  return null;
}

/**
 * Encodes a value (or null) as JSON exactly as the engine encodes it: the same members in the same
 * order, names sorted, and the same escapes as Go's encoding/json (including <, > and &). Unlike
 * encoding/json, which fails beyond 10,000 levels, it encodes trees of any depth.
 */
export function marshal(n: Node | null): string {
  return print(n, marshalValue);
}

// Pending is a value that a printer has yet to write.
export class Pending {
  v: Value;
  constructor(v: Value) {
    this.v = v;
  }
}

// print writes v with write, which writes a value as text and Pending values (its parts, such as
// the children of a node), and writes those in turn. It keeps the values to write on a stack of
// its own, so that it can write trees of any depth: parses build trees deeper than the JavaScript
// stack allows recursion (left recursion, foldl and OperatorsRule operators nest without nesting calls).
export function print(v: Value, write: (v: Value, out: (string | Pending)[]) => void): string {
  const b: string[] = [];
  const stack: (string | Pending)[] = [new Pending(v)];
  const parts: (string | Pending)[] = [];
  while (stack.length > 0) {
    const x = stack.pop()!;
    if (typeof x === "string") {
      b.push(x);
      continue;
    }
    parts.length = 0;
    write(x.v, parts);
    for (let i = parts.length - 1; i >= 0; i--) {
      stack.push(parts[i]!);
    }
  }
  return b.join("");
}

export function marshalElements(kids: readonly (Node | null)[], out: (string | Pending)[]): void {
  out.push("[");
  kids.forEach((c, i) => {
    if (i > 0) {
      out.push(",");
    }
    out.push(new Pending(c));
  });
  out.push("]");
}

export function marshalValue(v: Value, out: (string | Pending)[]): void {
  if (v === null) {
    out.push("null");
    return;
  }
  if (!(v instanceof Node)) {
    out.push(typeof v === "string" ? quoteJSON(v) : String(v));
    return;
  }
  const shape = nodeShape(v);
  switch (shape) {
    case shapeBox:
      // The box stands for its value.
      out.push(new Pending(v.box));
      return;
    case shapeString:
    case shapeTuple:
    case shapeList:
      // A node of a named node type names its type.
      out.push((v instanceof TypedNode ? '{"type":' + quoteJSON(v.type) + "," : "{") + '"start":' + v.start + ',"end":' + v.end + ',"value":');
      if (shape === shapeString) {
        out.push(quoteJSON(v.text));
      } else {
        marshalElements(v.children, out);
      }
      // Source information: the rule, and where the captures are.
      if (v.rule !== "") {
        out.push(',"rule":' + quoteJSON(v.rule));
      }
      if (v.labeled && v.fields.length > 0) {
        out.push(',"captures":{');
        captureLocations(v).forEach((c, i) => {
          out.push((i > 0 ? "," : "") + quoteJSON(c.name));
          if (c.side) {
            out.push(':{"value":', new Pending(c.value), "}");
          } else {
            out.push(':{"path":[' + c.path.join(",") + "]}");
          }
        });
        out.push("}");
      }
      out.push("}");
      return;
    case shapeError: {
      out.push('{"start":' + v.start + ',"end":' + v.end + ',"error":', new Pending(v.field("message")));
      const expected = lookupField(v, "expected");
      if (expected !== undefined) {
        out.push(',"expected":', new Pending(expected));
      }
      out.push("}");
      return;
    }
    case shapeTupleValue:
    case shapeListValue:
      marshalElements(v.children, out);
      return;
  }
  out.push('{"type":' + quoteJSON(v.type) + ',"start":' + v.start + ',"end":' + v.end + ',"fields":{');
  sortedFields(v.fields).forEach((f, i) => {
    out.push((i > 0 ? "," : "") + quoteJSON(f.name) + ":", new Pending(f.value));
  });
  out.push("}}");
}

export const hex = "0123456789abcdef";

export const replacementChar = String.fromCharCode(0xfffd);

// quoteJSON quotes s as Go's encoding/json does with HTML escaping.
export function quoteJSON(s: string): string {
  let out = '"';
  let from = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    let esc = "";
    if (c < 0x20 || c === 0x22 || c === 0x5c || c === 0x3c || c === 0x3e || c === 0x26) {
      switch (c) {
        case 0x22:
          esc = '\\"';
          break;
        case 0x5c:
          esc = "\\\\";
          break;
        case 0x08:
          esc = "\\b";
          break;
        case 0x0c:
          esc = "\\f";
          break;
        case 0x0a:
          esc = "\\n";
          break;
        case 0x0d:
          esc = "\\r";
          break;
        case 0x09:
          esc = "\\t";
          break;
        default:
          esc = "\\u00" + hex[c >> 4] + hex[c & 15];
      }
    } else if (c === 0x2028 || c === 0x2029) {
      esc = "\\u202" + hex[c & 15];
    } else if (c >= 0xd800 && c <= 0xdfff) {
      // A lone surrogate is not valid UTF-8: an invalid byte (see decodeBytes), which Go writes as
      // U+FFFD.
      if (c < 0xdc00 && i + 1 < s.length && (s.charCodeAt(i + 1) & 0xfc00) === 0xdc00) {
        i++;
        continue;
      }
      esc = replacementChar;
    } else {
      continue;
    }
    out += s.slice(from, i) + esc;
    from = i + 1;
  }
  return out + s.slice(from) + '"';
}

// SexprFrame is a step of sexpr, which keeps its own stack for deep trees.
export interface SexprFrame {
  v: Value;
  i: number;
  enter: boolean;
  labels: Map<Node, string[]> | null;
  side: CaptureLocation[];
  close: string;
}

export function sexprFrame(v: Value, labels: Map<Node, string[]> | null): SexprFrame {
  return { v, i: 0, enter: true, labels, side: [], close: "" };
}

// sexpr writes v as the engine's Node.String does (see Node.toString).
export function sexpr(v: Value): string {
  const b: string[] = [];
  const stack: SexprFrame[] = [sexprFrame(v, null)];
  while (stack.length > 0) {
    const f = stack[stack.length - 1]!;
    const n = f.v;
    if (!(n instanceof Node)) {
      b.push(sexprScalar(n));
      stack.pop();
      continue;
    }
    const sh = nodeShape(n);
    if (f.enter) {
      f.enter = false;
      switch (sh) {
        case shapeBox:
          f.v = n.box;
          f.enter = true;
          continue;
        case shapeString:
          if (n instanceof TypedNode) {
            b.push(n.type + "(" + quoteGo(n.text));
            f.close = ")" + ruleSuffix(n);
          } else {
            b.push(quoteGo(n.text));
            f.close = ruleSuffix(n);
          }
          f.i = -1;
          break;
        case shapeError: {
          b.push("error(" + quoteGo(String(n.field("message"))));
          const expected = lookupField(n, "expected");
          if (expected !== undefined) {
            b.push(" expected " + quoteGo(String(expected)));
          }
          b.push(")");
          f.i = -1;
          break;
        }
        case shapeTuple:
        case shapeTupleValue:
          b.push(nodeTypePrefix(n) + "(");
          f.close = ")" + ruleSuffix(n);
          if (sh === shapeTuple && n.labeled) {
            const labels = new Map<Node, string[]>();
            for (const c of captureLocations(n)) {
              if (c.side) {
                f.side.push(c);
                continue;
              }
              let x: Node = n;
              for (const i of c.path) {
                x = x.children[i]!;
              }
              const names = labels.get(x);
              if (names === undefined) {
                labels.set(x, [c.name]);
              } else {
                names.push(c.name);
              }
            }
            f.labels = labels;
          }
          break;
        case shapeList:
        case shapeListValue:
          b.push(nodeTypePrefix(n) + "[");
          f.close = "]" + ruleSuffix(n);
          break;
        default:
          b.push(n.type + "{");
          f.close = "}";
      }
    }
    if (f.i < 0) {
      b.push(f.close);
      stack.pop();
      continue;
    }
    if (sh === shapeStruct) {
      const fields = sortedFields(n.fields);
      if (f.i === fields.length) {
        b.push(f.close);
        stack.pop();
        continue;
      }
      if (f.i > 0) {
        b.push(", ");
      }
      const field = fields[f.i]!;
      b.push(field.name + ": ");
      f.i++;
      stack.push(sexprFrame(field.value, null));
      continue;
    }
    if (f.i === n.children.length) {
      f.side.forEach((c, j) => {
        if (f.i > 0 || j > 0) {
          b.push(" ");
        }
        b.push("&" + c.name + ":" + sexpr(c.value));
      });
      b.push(f.close);
      stack.pop();
      continue;
    }
    if (f.i > 0) {
      b.push(" ");
    }
    const c = n.children[f.i]!;
    f.i++;
    const labels = f.labels;
    if (labels !== null && c !== null) {
      for (const name of labels.get(c) ?? []) {
        b.push(name + ":");
      }
    }
    // A tuple nested in the node's own tuple holds the node's captures too.
    stack.push(sexprFrame(c, c !== null && nodeShape(c) === shapeTuple && c.rule === "" ? labels : null));
  }
  return b.join("");
}

// nodeTypePrefix returns the name that a node of a named node type puts before its opening
// bracket, or "".
export function nodeTypePrefix(n: Node): string {
  return n instanceof TypedNode ? n.type : "";
}

export function ruleSuffix(n: Node): string {
  return n.rule !== "" ? "@" + n.rule : "";
}

export function sexprScalar(v: Value): string {
  if (v === null) {
    return "nil";
  }
  if (typeof v === "string") {
    return quoteGo(v);
  }
  return String(v);
}

// printRuns is the table of the code points that Go's strconv.IsPrint accepts: the lengths of the
// alternating runs of code points that it rejects and accepts, from U+0000, in base 36 separated by
// commas. It comes from the Go that generates the parser (a test compares it with that table), so
// that quoteGo does not depend on the version of Unicode of the JavaScript runtime.
