// printStarts holds the starts of the runs of printRuns, decoded on first use.
export let printStarts: number[] | null = null;

// isPrint reports whether Go's strconv.IsPrint accepts r.
export function isPrint(r: number): boolean {
  let starts = printStarts;
  if (starts === null) {
    starts = [];
    let x = 0;
    for (const d of printRuns.split(",")) {
      x += parseInt(d, 36);
      starts.push(x);
    }
    printStarts = starts;
  }
  // The number of runs that start at or before r, which is odd in a run of accepted code points.
  let lo = 0;
  let hi = starts.length;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (starts[mid]! <= r) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return lo % 2 === 1;
}

// quoteGo quotes s as Go's strconv.Quote does.
export function quoteGo(s: string): string {
  let out = '"';
  for (const ch of s) {
    const r = ch.codePointAt(0) as number;
    if (r === 0x22 || r === 0x5c) {
      out += "\\" + ch;
    } else if ((r >= 0x20 && r < 0x7f) || (r >= 0x80 && isPrint(r))) {
      out += ch;
    } else if (r === 0x07) {
      out += "\\a";
    } else if (r === 0x08) {
      out += "\\b";
    } else if (r === 0x0c) {
      out += "\\f";
    } else if (r === 0x0a) {
      out += "\\n";
    } else if (r === 0x0d) {
      out += "\\r";
    } else if (r === 0x09) {
      out += "\\t";
    } else if (r === 0x0b) {
      out += "\\v";
    } else if (r < 0x20 || r === 0x7f) {
      out += "\\x" + hex[r >> 4] + hex[r & 15];
    } else if (r >= 0xdc80 && r <= 0xdcff) {
      out += "\\x" + hex[(r >> 4) & 15] + hex[r & 15]; // an invalid byte (see decodeBytes)
    } else if (r >= 0xd800 && r <= 0xdfff) {
      out += replacementChar; // other lone surrogates do not occur
    } else if (r < 0x10000) {
      out += "\\u" + r.toString(16).padStart(4, "0");
    } else {
      out += "\\U" + r.toString(16).padStart(8, "0");
    }
  }
  return out + '"';
}

/** SyntaxError reports that the input does not match the grammar. Its message is "line:col: reason". */
export class SyntaxError extends Error {
  /** The position of the error, in the position unit. */
  pos: number;
  /** The line and column (both from 1; the column in the position unit). */
  line: number;
  col: number;
  /** The descriptions of what was expected: names, then literals, then classes, each in byte order. The message shows at most the first ten. */
  expected: string[];
  /** The messages of @error attributes. */
  messages: string[];

  constructor(pos: number, line: number, col: number, expected: string[], messages: string[]) {
    super(`${line}:${col}: ${reason(expected, messages)}`);
    this.name = "SyntaxError";
    this.pos = pos;
    this.line = line;
    this.col = col;
    this.expected = expected;
    this.messages = messages;
  }

  /** Describes the error without its position (Message in Go). */
  reason(): string {
    return reason(this.expected, this.messages);
  }
}

export function reason(expected: string[], messages: string[]): string {
  if (messages.length > 0) {
    return messages.join("; ");
  }
  if (expected.length > 0) {
    const shown = Math.min(expected.length, expectedInMessage);
    let msg = "syntax error: expected " + expected.slice(0, shown).join(", ");
    if (shown < expected.length) msg += expectedTail(expected.length - shown);
    return msg;
  }
  return "syntax error";
}

// expectedInMessage is the number of expected entries that the message of a syntax error lists.
// A longer list is cut after them and ends with the count of the rest; SyntaxError.expected keeps
// every entry.
export const expectedInMessage = 10;

// expectedTail ends a message whose expected list is cut, rest entries before its end.
export function expectedTail(rest: number): string {
  return `, ... and ${rest} more`;
}

// expectedKind ranks an expected entry by its kind: a named entry (such as "end of input" or a
// rule name) is 0, a literal ("...") is 1 and a class ([...]) is 2.
export function expectedKind(s: string): number {
  if (s.length !== 0) {
    if (s.charCodeAt(0) === 0x22) return 1;
    if (s.charCodeAt(0) === 0x5b) return 2;
  }
  return 0;
}

// compareExpected orders expected entries: by kind (expectedKind), then by their bytes.
export function compareExpected(a: string, b: string): number {
  return expectedKind(a) - expectedKind(b) || compareStrings(a, b);
}

/**
 * Makes a SyntaxError without capturing a stack trace. Only the construction runs with the limit at
 * zero, so no charge, signal getter or interruption is made while it is lowered.
 */
function bareSyntaxError(pos: number, line: number, col: number, expected: string[], messages: string[]): SyntaxError {
  const v8 = Error as { stackTraceLimit?: number };
  const limit = v8.stackTraceLimit;
  if (typeof limit !== "number") {
    return new SyntaxError(pos, line, col, expected, messages);
  }
  v8.stackTraceLimit = 0;
  try {
    return new SyntaxError(pos, line, col, expected, messages);
  } finally {
    v8.stackTraceLimit = limit;
  }
}

/** SyntaxErrors lists the syntax errors recovered from with #recover. */
export class SyntaxErrors extends Error {
  errors: SyntaxError[];

  constructor(errors: SyntaxError[]) {
    super(errors.map((e) => e.message).join("\n"));
    this.name = "SyntaxErrors";
    this.errors = errors;
  }
}

/**
 * The result of a parse. A failed parse has a null node and an error: a SyntaxError, or an Error for
 * a runtime error in an action or too deep nesting. A parse that recovered from errors with #recover
 * has both the node and SyntaxErrors.
 */
export interface ParseResult {
  node: Node | null;
  error: Error | null;
}

// --- Rules ---

// R is the result of a matcher: a value (null for none) on success, undefined on failure.
export type R = Node | null | undefined;

export type Matcher = (p: Parser) => R;

export type Action = (c: Actx) => Value;

export type Frame = (Node | null)[];

export const emptyFrame: Frame = [];

export interface Rule {
  id: number;
  name: string;
  scope: string[]; // capture names of the rule body, in slot order
  body: (p: Parser, min: number) => R;
  action: Action | null;
  value: Shaper; // makes the value of a body without an action (see scopeValue)
  // memo means the rule's results are memoized. It is false for transient rules, whose entries
  // could never be reused.
  memo: boolean;
  // leader is the leader of a left-recursive cycle; its results are always memoized.
  leader: boolean;
  // rec means the rule is on a cycle of calls: its entries count against the nesting limit.
  rec: boolean;
  // cycle numbers the left-recursion cycle of a leader or member from 1, or is 0 for a rule on no
  // cycle. The results of the rules of a cycle depend on the growths of its leaders (CtxCall).
  cycle: number;
  // leaderBit is the bit of a leader in the present sets of the results of its cycle, or 0: the
  // first 32 leaders of each cycle have one.
  leaderBit: number;
  // seen is the rule's index among the memoized rules whose memoization is deferred to the second
  // call at a position (firstCall), or -1.
  seen: number;
  operatorsRule: OperatorsRule | null;
  novalue: boolean; // value-free twin, called where the value is discarded
  // splice means the rule makes no node of its own: its value is the result of its body as it is,
  // and the captures of its body end with it. Its callers take the elements of the value.
  splice: boolean;
  // where, if not "", names the rule in the message of a failed action, instead of name.
  where: string;
  // vars are the variables the rule or its callees read, sorted. Memo entries are keyed by their
  // values at the call, since definitions inside the rule are undone when it returns.
  vars: number[];
  // nodeType, if not "", is the named node type the rule's value is converted to.
  nodeType: string;
  // opNodeType, if not "", is the named node type every operator node of an Operators Rule is
  // converted to.
  opNodeType: string;
}

// Shaper is the static shape of an expression that the runtime converts its matcher's result with,
// packed in a number: shaperElems (the matcher returns the tuple node of its elements), shaperTuple
// (the value of a scope is the node of its tuple, rather than its one element), how the expression
// takes one element in bits 2 and 3 (singleNone, singlePass or singleTuple), and the number of
// valued elements from bit 5. Bit 4 is shaperShared.
export type Shaper = number;

export const shaperElems = 1;
export const shaperTuple = 2;
// shaperShared: the tuple node the matcher returns is the result of a splice rule, shared through its
// memo entry, so that a node that takes it as its own takes a copy.
export const shaperShared = 16;
export const singleNone = 0; // no value
export const singlePass = 1; // the one element
export const singleTuple = 2; // the node of the tuple of the elements

// shaperOne returns the one element of the result v.
export function shaperOne(s: Shaper, v: Node | null): Node | null {
  if ((s & shaperElems) !== 0) {
    return v === null || v.children.length === 0 ? null : v.children[0]!;
  }
  return v;
}

export function failBody(): R {
  return undefined;
}

export function mkRule(
  id: number,
  name: string,
  scope: string[],
  value: Shaper,
  memo: boolean,
  leader: boolean,
  seen: number,
  novalue: boolean,
  vars: number[],
): Rule {
  return {
    id,
    name,
    scope,
    body: failBody,
    action: null,
    value,
    memo,
    leader,
    rec: false,
    cycle: 0,
    leaderBit: 0,
    seen,
    operatorsRule: null,
    novalue,
    splice: false,
    where: "",
    vars,
    nodeType: "",
    opNodeType: "",
  };
}

/**
 * The per-grammar state that the generated code fills in once and that every parse reads. A parser
 * generated from one grammar owns one Grammar, so several grammars can share this runtime.
 */
export interface Grammar {
  // maxDepth is the default maximum nesting of recursive rule calls.
  readonly maxDepth: number;
  // sparse selects the sparse representation of the visited regions for large inputs.
  readonly sparse: boolean;
  // observable reports that the generated rules report their calls, so trace and profile options apply.
  readonly observable: boolean;
  // controlled reports that the generated rules spend budget, so the cancellation and limit options apply.
  readonly controlled: boolean;
  // sourceInfo reports that values record source information: the rule that produced each node and
  // where its captures are.
  sourceInfo: boolean;
  // initialVars holds the declared parser variables with their initial values, in declaration
  // order; every parse starts from them.
  readonly initialVars: [string, Value][];
  // initEnv is the environment of the initial values, and envDepth its depth; the first parse
  // builds them (undefined until then).
  initEnv: Env | null | undefined;
  envDepth: number;
  // descs maps expectation IDs to their descriptions. A grammar without expectations has none.
  descs: string[];
  // expectations reports that the parser was generated with the means to record expectations (the
  // descs table). A parse records them only when it asks with ParseOptions.expectations; otherwise
  // it records the farthest failure position only.
  expectations: boolean;
  // structFields holds the field names of each struct type.
  readonly structFields: Map<string, Set<string>>;
}

export function mkGrammar(maxDepth: number, sparse: boolean, observable: boolean, controlled = true): Grammar {
  return { maxDepth, sparse, observable, controlled, sourceInfo: false, initialVars: [], initEnv: undefined, envDepth: 0, descs: [], expectations: false, structFields: new Map() };
}

function ruleIn(table: Rule[], name: string): Rule | null {
  for (const r of table) {
    if (r.name === name) {
      return r;
    }
  }
  return null;
}

/**
 * Returns the start rule name of table, one of starts, or an error that names the rule and tells
 * whether the grammar defines it (defined lists the names of all its rules; table can hold fewer).
 */
export function startIn(table: Rule[], defined: readonly string[], starts: readonly string[], defaultStart: string, name: string): Rule | Error {
  if (name === "") name = defaultStart;
  if (starts.includes(name)) return ruleIn(table, name)!;
  if (name === "") return new Error("no start rule is given");
  if (name.startsWith("_")) return new Error("rule " + name + " is hidden: a rule whose name begins with an underscore is not an entry point");
  if (!defined.includes(name)) return new Error(`rule ${name} is not defined`);
  return new Error(`rule ${name} is not a start rule; parsing can begin only at a rule marked @start`);
}

/** Options for one invocation. Zero maxDepth selects the default of the grammar. */
export interface ParseOptions {
  /** Accumulate unfiltered rule metrics; requires host performance.now() and a parser generated with observability. */
  profile?: Profile | null;
  /** Synchronous scalar events; thrown callback values propagate unchanged. Requires a parser generated with observability. */
  trace?: (event: TraceEvent) => void;
  /** Named rules and descendants; empty selects all, unknown names select none. */
  traceRules?: readonly string[];
  /** Start depth is one; nonpositive values leave delivery unlimited. */
  traceMaxDepth?: number;
  unit?: Unit;
  maxDepth?: number;
  /** Records what a syntax error expects and the messages of @error; requires a parser generated with expectations. Without it an error carries the farthest failure position only. */
  expectations?: boolean;
  signal?: CancellationSignal | null;
  /** Budget limit. Zero selects the default of max(2^20, 1024 times the input length in the position unit); Unlimited disables the limit. */
  budget?: number;
  /** Longest input accepted, in the position unit. Zero and Unlimited, the default, set no bound; a longer input fails before any work with a ParseInterruptionError of kind "input-limit". */
  maxInput?: number;
}

/** The budget value that disables the budget limit. */
export const Unlimited = Number.MAX_SAFE_INTEGER;

const defaultBudgetFloor = 1 << 20;
const defaultBudgetPerUnit = 1024;

// inputUnits returns the length of input in the position unit. Inputs of at most defaultBudgetPerUnit units
// are not counted exactly: their default budget is the floor whatever their length.
function inputUnits(input: string | Uint8Array, unit: Unit, exact = false): number {
  const n = input.length;
  if (!exact && n <= defaultBudgetPerUnit) return n;
  let units = 0;
  if (typeof input === "string") {
    for (let i = 0; i < n; i++) {
      const c = input.charCodeAt(i);
      if (unit === Bytes) {
        if (c < 0x80) units += 1;
        else if (c < 0x800) units += 2;
        else if (c >= 0xd800 && c < 0xdc00 && i + 1 < n && (input.charCodeAt(i + 1) & 0xfc00) === 0xdc00) { units += 4; i++; }
        else units += 3;
      } else if (c >= 0xd800 && c < 0xdc00 && i + 1 < n && (input.charCodeAt(i + 1) & 0xfc00) === 0xdc00) { units += 1; i++; }
      else units += 1;
    }
    return units;
  }
  if (unit === Bytes) return n;
  // Decode as the parser does: each invalid byte is one U+FFFD code point.
  for (let i = 0; i < n; i += decodedSize) {
    decodeRune(input, i, n);
    units++;
  }
  return units;
}

// inputOverMax returns the length of input in the position unit when it exceeds max, and null
// otherwise. It counts only when the length of the input does not already bound the count by max.
function inputOverMax(input: string | Uint8Array, unit: Unit, max: number): number | null {
  const n = input.length;
  // A UTF-16 code unit is at most three bytes; a code point is at most one unit.
  if ((typeof input === "string" && unit === Bytes ? n * 3 : n) <= max) return null;
  const units = inputUnits(input, unit, true);
  return units > max ? units : null;
}

// defaultBudget returns max(2^20, 1024*n), kept below Unlimited.
function defaultBudget(n: number): number {
  return Math.min(Math.max(defaultBudgetFloor, n * defaultBudgetPerUnit), Unlimited - 1);
}

/**
 * The options of a parser generated without budget controls: those of ParseOptions except the
 * cancellation signal and the budget limits.
 */
export type PlainParseOptions = Omit<ParseOptions, "signal" | "budget" | "maxInput">;

// resolveOptions validates options for a parse of input. A zero budget of a parser generated with budget
// controls resolves to the default budget of the input, and Unlimited resolves to no budget limit (zero).
export function resolveOptions(g: Grammar, options: ParseOptions | undefined, input: string | Uint8Array): ResolvedParseOptions | Error {
  if (!g.controlled && (options?.signal != null || ((options?.budget ?? 0) !== 0 && options?.budget !== Unlimited) || ((options?.maxInput ?? 0) !== 0 && options?.maxInput !== Unlimited))) {
    return new Error("this parser was generated without budget controls (generate with -budget-controls to use signal, budget and maxInput)");
  }
  if (!g.observable && (options?.profile != null || options?.trace != null || options?.traceRules !== undefined || options?.traceMaxDepth !== undefined)) {
    return new Error("trace and profile options are only supported by a parser generated with observability");
  }
  const profile = options?.profile ?? null;
  if (profile !== null && (!(profile instanceof Profile) || !profileData.has(profile))) return new Error("profile must be a Profile");
  const profileClock = profile === null ? null : resolveProfileClock();
  if (profileClock instanceof Error) return profileClock;
  if (options?.expectations === true && !g.expectations) {
    return new Error("this parser was generated without expectations (generate with expectations to use the expectations option)");
  }
  const trace = options?.trace ?? null;
  const traceMaxDepth = options?.traceMaxDepth ?? 0;
  if (trace !== null && typeof trace !== "function") return new Error("trace must be a function");
  if (!Number.isSafeInteger(traceMaxDepth)) return new Error("trace max depth must be a safe integer");
  const traceRules = Array.from(options?.traceRules ?? []);
  const unit = options?.unit === Bytes ? Bytes : CodePoints;
  const depth = options?.maxDepth ?? 0;
  const signal = options?.signal ?? null;
  const requested = options?.budget ?? 0;
  if (!Number.isSafeInteger(depth) || depth < 0) {
    return new Error(`max depth must be a non-negative safe integer: ${depth}`);
  }
  if (!Number.isSafeInteger(requested) || requested < 0) {
    return new Error(`budget must be a non-negative safe integer: ${requested}`);
  }
  const maxInput = options?.maxInput ?? 0;
  if (!Number.isSafeInteger(maxInput) || maxInput < 0) {
    return new Error(`max input must be a non-negative safe integer: ${maxInput}`);
  }
  if (maxInput !== 0 && maxInput !== Unlimited) {
    const over = inputOverMax(input, unit, maxInput);
    if (over !== null) return new ParseInterruptionError("input-limit", maxInput, 0, over);
  }
  const budget = requested === Unlimited ? 0 : requested !== 0 ? requested : g.controlled ? defaultBudget(inputUnits(input, unit)) : 0;
  return { unit, maxDepth: depth === 0 ? g.maxDepth : depth, expectations: options?.expectations === true, signal, budget, trace, traceRules, traceMaxDepth, profile, profileClock };
}

// run parses the whole input of the grammar g with rule r of a rule table with seen rules that have rule.seen set.
export function run(g: Grammar, r: Rule, seen: number, input: string | Uint8Array, unit: Unit | undefined, maxDepth = g.maxDepth, control: BudgetControl | null = null, traceOptions: ResolvedParseOptions | null = null): ParseResult {
  let p: Parser | null = null;
  try {
    // Made inside the try, so that decoding the input fails as parsing does.
    p = new Parser(g, input, unit === Bytes ? Bytes : CodePoints, seen, maxDepth, control);
    p.expectations = traceOptions?.expectations === true;
    p.observation = traceOptions?.profile != null ? new ProfileObservation(traceOptions) : traceOptions?.trace == null ? null : new Observation(traceOptions);
    return result(p, p.call(r, 0));
  } catch (x) {
    if (x instanceof Fatal) {
      if (control !== null) throw x;
      return { node: null, error: x.err };
    }
    if (isStackOverflow(x)) {
      // The JavaScript stack is smaller than the nesting limit allows.
      return {
        node: null,
        error: new Error(`nesting too deep: the JavaScript stack overflowed at ${p === null ? 0 : p.depth} nested recursive rule calls`),
      };
    }
    throw x;
  } finally {
    p?.observation?.release();
    if (p !== null) p.observation = null;
  }
}

// isStackOverflow reports whether x is what a JavaScript engine throws when the stack is exhausted:
// a RangeError "Maximum call stack size exceeded" in V8 and JavaScriptCore, an InternalError "too much
// recursion" in SpiderMonkey.
export function isStackOverflow(x: unknown): boolean {
  return (
    x instanceof Error && (x instanceof RangeError || x.name === "InternalError") && /stack|recursion/i.test(x.message)
  );
}

// result returns the result of a parse whose call of the start rule returned v.
export function result(p: Parser, v: R): ParseResult {
  if (v !== undefined && p.pos === p.n) {
    if (p.recovered.length > 0) {
      if (p.control !== null) reserveRecoveredMessageSpend(p.recovered, p.control);
      const error = new SyntaxErrors(p.recovered);
      p.control?.check();
      return { node: v, error };
    }
    return { node: v, error: null };
  }
  if (v !== undefined) {
    p.expect(p.pos, idEndInput);
  }
  return { node: null, error: p.makeError(p.farthest, p.control === null ? p.exp.slice(p.expBase, p.expTop) : copyIDsSpend(p.exp, p.expBase, p.expTop, p.control)) };
}

// --- Input ---

// decodedSize is the size of the sequence decodeRune decoded last.
export let decodedSize = 0;

// decodeRune decodes the UTF-8 sequence at b[i] (i < n) as Go's utf8.DecodeRune does: an invalid
// or truncated sequence decodes as U+FFFD of one byte.
export function decodeRune(b: Uint8Array, i: number, n: number): number {
  const c0 = b[i]!;
  decodedSize = 1;
  if (c0 < 0x80) {
    return c0;
  }
  if (c0 < 0xc2 || c0 > 0xf4) {
    return 0xfffd;
  }
  const c1 = i + 1 < n ? b[i + 1]! : 0;
  if (c0 < 0xe0) {
    if ((c1 & 0xc0) !== 0x80) {
      return 0xfffd;
    }
    decodedSize = 2;
    return ((c0 & 0x1f) << 6) | (c1 & 0x3f);
  }
  const lo = c0 === 0xe0 ? 0xa0 : c0 === 0xf0 ? 0x90 : 0x80;
  const hi = c0 === 0xed ? 0x9f : c0 === 0xf4 ? 0x8f : 0xbf;
  if (c1 < lo || c1 > hi) {
    return 0xfffd;
  }
  const c2 = i + 2 < n ? b[i + 2]! : 0;
  if ((c2 & 0xc0) !== 0x80) {
    return 0xfffd;
  }
  if (c0 < 0xf0) {
    decodedSize = 3;
    return ((c0 & 0x0f) << 12) | ((c1 & 0x3f) << 6) | (c2 & 0x3f);
  }
  const c3 = i + 3 < n ? b[i + 3]! : 0;
  if ((c3 & 0xc0) !== 0x80) {
    return 0xfffd;
  }
  decodedSize = 4;
  return ((c0 & 0x07) << 18) | ((c1 & 0x3f) << 12) | ((c2 & 0x3f) << 6) | (c3 & 0x3f);
}

// encodeUTF8 encodes s in UTF-8, with lone surrogates as U+FFFD.
export function encodeUTF8(s: string): Uint8Array {
  const out = new Uint8Array(utf8EncodingLen(s));
  let j = 0;
  for (let i = 0; i < s.length; i++) {
    let c = s.charCodeAt(i);
    if (c < 0x80) {
      out[j++] = c;
      continue;
    }
    if (c >= 0xd800 && c <= 0xdfff) {
      if (c < 0xdc00 && i + 1 < s.length && (s.charCodeAt(i + 1) & 0xfc00) === 0xdc00) {
        c = 0x10000 + ((c - 0xd800) << 10) + (s.charCodeAt(i + 1) - 0xdc00);
        i++;
      } else {
        c = 0xfffd;
      }
    }
    if (c < 0x800) {
      out[j++] = 0xc0 | (c >> 6);
      out[j++] = 0x80 | (c & 0x3f);
    } else if (c < 0x10000) {
      out[j++] = 0xe0 | (c >> 12);
      out[j++] = 0x80 | ((c >> 6) & 0x3f);
      out[j++] = 0x80 | (c & 0x3f);
    } else {
      out[j++] = 0xf0 | (c >> 18);
      out[j++] = 0x80 | ((c >> 12) & 0x3f);
      out[j++] = 0x80 | ((c >> 6) & 0x3f);
      out[j++] = 0x80 | (c & 0x3f);
    }
  }
  return out;
}

// utf8EncodingLen sizes caller strings, replacing every lone surrogate with U+FFFD.
export function utf8EncodingLen(s: string): number {
  let n = s.length;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c < 0x80) {
      continue;
    }
    if (c < 0x800) {
      n++;
    } else if (c >= 0xd800 && c < 0xdc00 && i + 1 < s.length && (s.charCodeAt(i + 1) & 0xfc00) === 0xdc00) {
      n += 2; // a pair: 2 units, 4 bytes
      i++;
    } else {
      n += 2; // a lone surrogate is encoded as U+FFFD
    }
  }
  return n;
}

// utf8Len returns the length of s in UTF-8: the number of bytes utf8Bytes returns.
export function utf8Len(s: string): number {
  let n = s.length;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c < 0x80) {
      continue;
    }
    if (c < 0x800) {
      n++;
    } else if (c >= 0xd800 && c < 0xdc00 && i + 1 < s.length && (s.charCodeAt(i + 1) & 0xfc00) === 0xdc00) {
      n += 2; // a pair: 2 units, 4 bytes
      i++;
    } else if (c < 0xdc80 || c > 0xdcff) {
      n += 2; // an invalid byte (see decodeBytes) is one byte
    }
  }
  return n;
}

// utf8Bytes returns the bytes of s: its UTF-8 encoding, with the surrogates that stand for invalid
// bytes (see decodeBytes) as those bytes.
export function utf8Bytes(s: string): number[] {
  const out: number[] = [];
  for (const ch of s) {
    const c = ch.codePointAt(0)!;
    if (c >= 0xdc80 && c <= 0xdcff) {
      out.push(c & 0xff);
      continue;
    }
    for (const x of encodeUTF8(ch)) {
      out.push(x);
    }
  }
  return out;
}

// isByte reports whether s[i] is a surrogate that stands for an invalid byte (see decodeBytes).
export function isByte(s: string, i: number): boolean {
  const c = s.charCodeAt(i);
  return c >= 0xdc80 && c <= 0xdcff && !(i > 0 && (s.charCodeAt(i - 1) & 0xfc00) === 0xd800);
}

// runeCount returns the number of code points in s.
export function runeCount(s: string): number {
  let n = s.length;
  for (let i = 0; i + 1 < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 0xd800 && c < 0xdc00 && (s.charCodeAt(i + 1) & 0xfc00) === 0xdc00) {
      n--;
      i++;
    }
  }
  return n;
}

// wellFormed replaces the lone surrogates of s with U+FFFD.
export function wellFormed(s: string): string {
  const parts: string[] = [];
  let from = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdfff) {
      if (c < 0xdc00 && i + 1 < s.length && (s.charCodeAt(i + 1) & 0xfc00) === 0xdc00) {
        i++;
        continue;
      }
      parts.push(s.slice(from, i), replacementChar);
      from = i + 1;
    }
  }
  if (from === 0) {
    return s;
  }
  parts.push(s.slice(from));
  return parts.join("");
}

// compareStrings compares strings by the byte order of their UTF-8 encodings (Go's string order),
// which is the order of their code points.
export function compareStrings(a: string, b: string): number {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    let x = a.charCodeAt(i);
    let y = b.charCodeAt(i);
    if (x !== y) {
      if (isByte(a, i) || isByte(b, i)) {
        // An invalid byte compares as a byte with the bytes of the other string.
        const p = utf8Bytes(a.slice(i));
        const q = utf8Bytes(b.slice(i));
        for (let k = 0; k < p.length && k < q.length; k++) {
          if (p[k] !== q[k]) {
            return p[k]! < q[k]! ? -1 : 1;
          }
        }
        return p.length < q.length ? -1 : p.length > q.length ? 1 : 0;
      }
      if (x >= 0xd800 && y >= 0xd800) {
        // Surrogates (code points above U+FFFF) sort after U+E000-U+FFFF.
        x = x >= 0xe000 ? x - 0x800 : x + 0x2000;
        y = y >= 0xe000 ? y - 0x800 : y + 0x2000;
      }
      return x < y ? -1 : 1;
    }
  }
  return a.length < b.length ? -1 : a.length > b.length ? 1 : 0;
}

// --- Parser state ---

// An expectation is an index into descs; with msgBit set, it is an @error message.
export const msgBit = 1 << 30;
// expFar is the only entry of an expectation record in a parse that does not record expectations.
// It stands for a failure at the position of the record and describes nothing.
export const expFar = 1 << 29;

// Expectations at the start of every descs table.
export const idAny = 0;
export const idBeginInput = 1;
export const idEndInput = 2;
export const idBeginLine = 3;
export const idEndLine = 4;

// Env is a persistent vector with one current value per declared variable, indexed by the
// variable's slot (its position in declaration order). A vector of at most envWidth variables is
// one array of values (a leaf); a larger one is a trie of arrays whose elements are the child
// arrays, whose depth (the levels above the leaves) every holder knows from the variable count.
// Environments saved for rollback are never modified: a rebind copies the arrays on the path to
// its slot and shares the rest.
export type Env = unknown[];

const envBits = 4;
const envWidth = 1 << envBits;
const envMask = envWidth - 1;

// envDepthOf returns the number of levels above the leaves of an environment of n variables.
export function envDepthOf(n: number): number {
  let levels = 0;
  for (let limit = envWidth; n > limit; limit *= envWidth) levels++;
  return levels;
}

// newEnv returns the environment that holds vals, with depth envDepthOf(vals.length).
export function newEnv(vals: Value[], depth: number): Env | null {
  if (vals.length === 0) return null;
  if (depth === 0) return vals.slice();
  const span = 2 ** (envBits * depth);
  const kids: Env[] = [];
  for (let lo = 0; lo < vals.length; lo += span) kids.push(newEnv(vals.slice(lo, lo + span), depth - 1)!);
  return kids;
}

// envGet returns the value of the variable in slot i.
export function envGet(e: Env, i: number, depth: number): Value {
  for (let l = depth; l > 0; l--) e = e[Math.floor(i / 2 ** (envBits * l)) & envMask] as Env;
  return e[i & envMask] as Value;
}

// envSet returns the environment that differs from e in the value of slot i. The copied arrays
// are those on the path to the slot: depth+1 of them.
export function envSet(e: Env, i: number, depth: number, v: Value): Env {
  const out = e.slice();
  if (depth === 0) {
    out[i] = v;
    return out;
  }
  const k = Math.floor(i / 2 ** (envBits * depth)) & envMask;
  out[k] = envSet(e[k] as Env, i % 2 ** (envBits * depth), depth - 1, v);
  return out;
}

export interface MemoEntry {
  node: R;
  errs: SyntaxError[]; // errors recovered in this call, recorded again on reuse
  expected: number[]; // expectations at far, recorded again on reuse
  next: MemoEntry | null; // next entry at the same position
  env: Value[] | null; // values of the rule's variables at the call (memo key)
  end: number;
  far: number;
  rule: number;
  min: number;
  ok: boolean;
  // silent means the result was computed inside a lookahead without recording expectations;
  // outside lookaheads it is computed again.
  silent: boolean;
  // present is the set of leaders (Rule.leaderBit) that grew at the position when the result of a
  // rule of a cycle was evaluated; it answers a call where no other leader grows (memoAllows).
  present: number;
}

export function newEntry(node: R, ok: boolean, end: number, silent: boolean, errs: SyntaxError[]): MemoEntry {
  return { node, errs, expected: noExp, next: null, env: null, end, far: 0, rule: 0, min: 0, ok, silent, present: 0 };
}

export const noExp: number[] = [];

// SkipRecord is what the rest of a walk of a skip-run site from a position did: where it ended, and
// its farthest failure and the expectations there (see skipBegin).
interface SkipRecord {
  end: number;
  far: number;
  exp: number[];
}

// SkipSlots holds the slots of a site: a bit for each position from base on in the 32-bit words
// marks, set when the slot is not fresh, and the records of the recorded slots by position.
class SkipSlots {
  base = 0;
  marks: number[] = [];
  recs = new Map<number, SkipRecord>();

  // marked reports whether the slot of pos is not fresh.
  marked(pos: number): boolean {
    const i = pos - this.base;
    return i >= 0 && i >>> 5 < this.marks.length && (this.marks[i >>> 5]! & (1 << (i & 31))) !== 0;
  }

  // put marks the slot of pos and stores its record r, if any. Room made for bits before base is as
  // large as the bits, so walks that start farther and farther back copy them a logarithmic number
  // of times.
  put(pos: number, r: SkipRecord | null): void {
    if (this.marks.length === 0) {
      this.base = pos - (pos & 31);
    } else if (pos < this.base) {
      let base = Math.max(0, Math.min(pos, this.base - 32 * this.marks.length));
      base -= base & 31;
      const room: number[] = new Array<number>((this.base - base) >>> 5).fill(0);
      this.marks = room.concat(this.marks);
      this.base = base;
    }
    const w = (pos - this.base) >>> 5;
    while (this.marks.length <= w) {
      this.marks.push(0);
    }
    this.marks[w] = this.marks[w]! | (1 << ((pos - this.base) & 31));
    if (r !== null) {
      this.recs.set(pos, r);
    }
  }
}

// SkipVisit is a recording visit of the walk in progress.
interface SkipVisit {
  pos: number;
  far: number;
  exp: number[];
}

// mergeSkipExpected returns the expectations a, then those of b not in a.
function mergeSkipExpected(a: number[], b: number[]): number[] {
  if (a.length === 0) {
    return b;
  }
  let out = a;
  for (const x of b) {
    if (!a.includes(x)) {
      if (out === a) {
        out = a.slice();
      }
      out.push(x);
    }
  }
  return out;
}
export const noErrs: SyntaxError[] = [];

/** memoScan is how many entries of a position's chain a lookup walks before it consults the
 * position's hash index; see runtime/memo_index.go. */
const memoScan = 32;

/**
 * memoKeyHash hashes a memo key deterministically, so that budgeted costs do not vary between runs.
 * Values that are not hashed (nodes) all hash alike and are told apart by the key comparison. The
 * hash costs one step plus one for each variable of the key, and the characters of string values,
 * as comparing them would.
 */
function memoKeyHash(rule: number, min: number, env: Value[] | null, control: BudgetControl | null): number {
  let h = 0x811c9dc5;
  const mix = (x: number): void => {
    h = Math.imul(h ^ x, 0x01000193);
    h ^= h >>> 15;
  };
  mix(rule);
  mix(min);
  if (env !== null) {
    control?.charge(1 + env.length);
    for (const v of env) {
      if (v === null) {
        mix(0);
      } else if (typeof v === "string") {
        mix(v.length);
        for (let from = 0; from < v.length; from += 128) {
          const end = Math.min(from + 128, v.length);
          control?.charge(end - from);
          for (let i = from; i < end; i++) {
            mix(v.charCodeAt(i));
          }
        }
      } else if (typeof v === "number") {
        mix(v | 0); // +0 and -0 are equal
      } else if (typeof v === "bigint") {
        mix(Number(BigInt.asIntN(32, v)));
      } else if (typeof v === "boolean") {
        mix(v ? 1 : 0);
      } else {
        mix(0x7f4a7c15);
      }
    }
  } else {
    control?.charge(1);
  }
  return h >>> 0;
}

// sameValues reports whether two lists of variable values are equal.
export function sameValues(a: Value[] | null, b: Value[] | null, control: BudgetControl | null = null): boolean {
  if (a === null || b === null) {
    return (a === null ? 0 : a.length) === (b === null ? 0 : b.length);
  }
  if (a.length !== b.length) {
    return false;
  }
  for (let i = 0; i < a.length; i++) {
    if (control !== null) {
      control.charge(1);
      const x = a[i], y = b[i];
      if (typeof x === "string" && typeof y === "string") {
        if (x.length !== y.length) return false;
        for (let from = 0; from < x.length; from += 128) {
          const end = Math.min(from + 128, x.length);
          control.charge(end - from);
          if (x.slice(from, end) !== y.slice(from, end)) return false;
        }
        continue;
      }
    }
    if (a[i] !== b[i]) {
      return false;
    }
  }
  return true;
}

// Lit is a literal: its code points and its UTF-8 bytes (Go's []rune and []byte of the literal).
export interface Lit {
  text: string;
  cps: number[];
  bytes: number[];
}

// foldASCII maps A-Z to a-z and leaves every other code point as it is.
function foldASCII(r: number): number {
  return r >= 65 && r <= 90 ? r + 32 : r;
}

// --- The dependency memo of left recursion ---
//
// The result of a call of a rule of a left-recursion cycle at a position is a function of the
// growths of the cycle in progress there, its context. A result that read no seed and made no
// observation goes to the memo with its present set; any other result goes to the table of its
// context, keyed by the identities of the seeds it read and the outcomes of the lookaheads it
// observed. See Parser.ctxEnter and the Go runtime's runtime/context_memo.go, which this mirrors.

// failSeed is the identity of the failure that every growth starts from.
const failSeed = 1;

// maxCtxDeps is the most dependencies a result in a context table can have; a result with more is
// evaluated again.
const maxCtxDeps = 6;

// The value of an observation for which no outcome is memoized. Outcomes are 0 and 1.
const obsNone = -1;

// The kinds of dependencies: a seed read (idx is its index in gamma, val its identity), the outcome
// val of the lookahead site idx in the context of depth d, and a seed read by a lookahead that an
// observation at depth d stands for.
const depSeed = 0;
const depObs = 1;
const depShadow = 2;

// The kinds of memoized evaluations in a context table.
const ctxCallKind = 0;
const ctxStepKind = 1;
const ctxLookKind = 2;

// The ways a memoized call stores its result (Parser.ctxPop): nowhere, as the call is in a context
// that cannot be told from others; in the memo; in the table of the context.
export const storeNone = 0;
export const storeMemo = 1;
export const storeCtx = 2;

// CtxResult is a result that a context keeps: a seed, the result of a growth step, or the result of
// a call that read a seed.
export interface CtxResult {
  node: R;
  errs: SyntaxError[];
  expected: number[];
  end: number;
  far: number;
  ok: boolean;
  silent: boolean;
}

export function newCtxResult(node: R, end: number, silent: boolean, errs: SyntaxError[], far: number, expected: number[]): CtxResult {
  return { node, errs, expected, end, far, ok: node !== undefined, silent };
}

// CtxCall is the context of a memoized call of a rule of a cycle (Parser.ctxEnter): the index in
// gamma of the first growth of the context, its present set, whether the call is in a context,
// whether the present set tells the context from others, and whether the call records its
// dependencies.
export interface CtxCall {
  gp: number;
  present: number;
  ctx: boolean;
  known: boolean;
  framed: boolean;
}

// noCtx is the context of a call where no growth is in progress, which nothing changes.
export const noCtx: CtxCall = { gp: 0, present: 0, ctx: false, known: false, framed: false };

export function newCtxCall(): CtxCall {
  return { gp: 0, present: 0, ctx: false, known: false, framed: false };
}

// memoAllows reports whether a result in the memo with the present set present answers a call in
// the context c: every leader that grows there grew when it was evaluated, and did not matter to it.
export function memoAllows(c: CtxCall, present: number): boolean {
  return !c.ctx || c.known && (c.present & ~present) === 0;
}

// GrowRec is a growth in progress: the leader's key, its position, cycle and bit, its current seed
// and the seed's identity.
interface GrowRec {
  rule: number;
  min: number;
  pos: number;
  cycle: number;
  bit: number;
  seed: CtxResult;
  id: number;
}

interface Dep {
  kind: number;
  idx: number;
  d: number;
  val: number;
}

const noDeps: Dep[] = [];

// DepFrame records the dependencies of an evaluation at pos in the context gamma[:depth], whose
// growths at pos are gamma[gp:depth]. Its dependencies are deps[base:] while it is the innermost
// frame.
interface DepFrame {
  pos: number;
  gp: number;
  depth: number;
  base: number;
}

// Sdep is a stored dependency: a seed (or shadow) by the leader's key, or an observation by site.
interface Sdep {
  kind: number;
  rule: number;
  min: number;
  site: number;
  val: number;
}

const noSdeps: Sdep[] = [];

// headKey is the key of the results of a call, a growth step or a lookahead in a context table.
function headKey(kind: number, id: number, min: number, present: number): string {
  return kind + "," + id + "," + min + "," + present;
}

// CtxSet is the dependencies of one shape that results of a head have: the keys of the leaders whose
// seeds they read (rule and level pairs) and the sites they observed, and the results by the values
// of those.
interface CtxSet {
  seeds: number[];
  obs: number[];
  vals: Map<string, CtxSlot>;
}

// CtxSlot is a result in a context table: the result, and for a growth step the identity of its
// result and what the step itself recorded. For a lookahead, id is its outcome.
interface CtxSlot {
  e: CtxResult | null;
  id: number;
  far: number;
  exp: number[];
  silent: boolean;
  env: Value[] | null;
  deps: Sdep[];
  next: CtxSlot | null;
}

function newSlot(e: CtxResult | null, id: number, env: Value[] | null): CtxSlot {
  return { e, id, far: 0, exp: noExp, silent: false, env, deps: noSdeps, next: null };
}

// JumpRec takes a growth from a seed to the seed at the end of a run of steps that read no other
// seed, with what those steps recorded.
interface JumpRec {
  end: CtxResult;
  id: number;
  far: number;
  exp: number[];
  silent: boolean;
  deps: Sdep[];
}

function jumpKey(g: GrowState, seed: number): string {
  return g.rule + "," + g.min + "," + g.present + "," + seed;
}

// CtxTable is the table of the growths of one cycle at a position: what the calls and growth steps
// there memoized while such a growth is in progress. It is dropped when the first of those growths
// ends.
interface CtxTable {
  pos: number;
  depth: number; // the index in gamma of the first of the growths
  heads: Map<string, CtxSet[]>;
  jumps: Map<string, JumpRec[]> | null;
  canon: Map<string, { e: CtxResult; id: number }> | null;
}

// GrowState is the state of the growth of a leader: its key, start and recovered errors, its index
// in gamma and that of the first growth of its cycle at the position, whether it grows in a context
// (whose steps are memoized with the present set present), whether it is done, the expectation mark
// of the step being evaluated in a context, and the steps since the last step that read a seed other
// than the leader's own.
export interface GrowState {
  rule: number;
  min: number;
  start: number;
  rec: number;
  gi: number;
  gp: number;
  ctx: boolean;
  present: number;
  done: boolean;
  exp: number;
  run: RunStep[];
}

// RunStep is a step of a run of a growth: the seed it started from and what it recorded.
interface RunStep {
  seed: number;
  far: number;
  exp: number[];
  silent: boolean;
  deps: Sdep[];
}

function sameNumbers(a: number[], b: number[]): boolean {
  if (a.length !== b.length) {
    return false;
  }
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) {
      return false;
    }
  }
  return true;
}

// mergeSdeps returns the union of two lists of stored dependencies.
function mergeSdeps(a: Sdep[], b: Sdep[]): Sdep[] {
  if (b.length === 0) {
    return a;
  }
  const out = a.slice();
  for (const d of b) {
    if (!out.some((x) => x.kind === d.kind && x.rule === d.rule && x.min === d.min && x.site === d.site && x.val === d.val)) {
      out.push(d);
    }
  }
  return out;
}

export class Parser {
  observation: Observation | null = null; // set for the duration of an observed parse
  readonly g: Grammar;
  readonly sourceInfo: boolean; // g.sourceInfo, read on every node
  unit: Unit;
  cps: Int32Array; // code points (CodePoints)
  bs: Uint8Array; // the input (Bytes)
  n: number; // input length in units
  // src is the input as a string (with U+FFFD for invalid UTF-8), and offs maps positions to
  // offsets in src (null when they are the same).
  src: string;
  offs: Int32Array | null;
  pos = 0;
  psize = 0; // the size of the character peek returned

  readonly maxDepth: number; // invocation-local maximum nesting
  depth = 0; // nesting of recursive rule calls
  created: Node[] = []; // struct nodes made by the action being evaluated (from Actx.cbase)
  env: Env | null = null;
  envDepth = 0; // the depth of env (Grammar.envDepth)
  frame: Frame = emptyFrame;
  trail: { f: Frame; slot: number; old: Node | null }[] = [];
  cut = false;

  // The memo: entries per position, chained.
  slots: (MemoEntry | null | undefined)[] = [];
  // seen is a bit set of the (position, rule) pairs called once (firstCall), with stride bits per
  // position.
  seen: Int32Array = new Int32Array(0);
  stride: number;
  sparse: boolean;
  seenPages: ((number | undefined)[] | undefined)[] | null = null;
  seenPageChunks: Int32Array[] | null = null;
  seenPageCount = 0;
  // calls and repeats count, per rule number, the calls and the repeated calls at a position; once
  // repeats are frequent, the rule is memoized on the first call (eager).
  calls: Int32Array;
  repeats: Int32Array;
  eager: Uint8Array;

  // silent is positive inside lookaheads, where expectations are not recorded.
  silent = 0;
  // The dependency memo of left recursion (see CtxCall): the growths in progress, the frames that
  // record dependencies and their dependencies, the dependencies a call ended (ctxPop), the tables
  // of the contexts, the lookaheads in progress (their sites, -1 for one that records nothing), the
  // lookahead sites whose outcomes are being looked up (obsValue), and the last seed identity.
  gamma: GrowRec[] = [];
  depFrames: DepFrame[] = [];
  deps: Dep[] = [];
  popped: Dep[] = [];
  ctxs: CtxTable[] = [];
  looks: number[] = [];
  lookRecs: number[] = []; // the recovered errors at the start of each lookahead in looks
  foundSet: CtxSet | null = null; // the set of the result that ctxFind last returned
  obsGuard: number[] = [];
  seedSeq = 0;
  farthest = 0;
  // expectations makes expect record expectations (ParseOptions.expectations). Without it a record
  // holds at most expFar.
  expectations = false;
  // exp[expBase:expTop] are the current expectations, all expected at farthest. The records of
  // enclosing isolated calls are below expBase.
  exp: number[] = [];
  expBase = 0;
  expTop = 0;
  lastKept: number[] = noExp;
  isoStack: number[] = [];
  isoIds: number[] = noExp;

  recovered: SyntaxError[] = [];

  kidStack: (Node | null)[] = []; // gathers repetition children and list elements
  lines: number[] | null = null; // positions where lines start (makeError)
  ac: Actx;
  saved: (Node | null)[] = []; // captures saved across a reset in longest

  // skipTables are the slots of the walks of skip-run sites, indexed by 2*site, plus 1 in a
  // lookahead. The walk in progress has the slots skipSlots (undefined until a walk of the site
  // first writes one, at skipTables[skipTable]) and the recording visits skipVisits;
  // skipRecording reports that it records (it met a position that is not fresh); skipOpen
  // reports that the last visit's iteration runs with its expectations isolated (the enclosing
  // record is skipFar and skipBase); skipHitRec is the record the walk stopped at, if any. Walks do
  // not nest: a site's element runs no #recover, so no other skip expression.
  skipTables: (SkipSlots | undefined)[] = [];
  skipSlots: SkipSlots | undefined = undefined;
  skipTable = 0;
  skipPrev = -1;
  skipVisits: SkipVisit[] = [];
  skipRecording = false;
  skipOpen = false;
  skipFar = 0;
  skipBase = 0;
  skipHitRec: SkipRecord | null = null;

  readonly control: BudgetControl | null;

  spend(n = 1): void { this.control?.charge(n); }

  constructor(g: Grammar, input: string | Uint8Array, unit: Unit, stride: number, maxDepth: number, control: BudgetControl | null = null) {
    this.g = g;
    this.sourceInfo = g.sourceInfo;
    this.control = control;
    this.unit = unit;
    this.maxDepth = maxDepth;
    if (g.initEnv === undefined) {
      g.envDepth = envDepthOf(g.initialVars.length);
      g.initEnv = newEnv(g.initialVars.map(([, val]) => val), g.envDepth);
    }
    this.env = g.initEnv;
    this.envDepth = g.envDepth;
    this.stride = stride;
    this.calls = new Int32Array(stride);
    this.repeats = new Int32Array(stride);
    this.eager = new Uint8Array(stride);
    this.ac = new Actx(this);
    this.cps = new Int32Array(0);
    this.bs = new Uint8Array(0);
    this.offs = null;
    if (control !== null) {
      if (unit === Bytes) {
        this.bs = typeof input === "string" ? encodeUTF8Spend(input, control) : input;
        this.n = this.bs.length;
        this.src = this.decodeBytesSpend();
      } else if (typeof input === "string") {
        this.src = this.decodeStringSpend(input);
        this.n = this.cps.length;
      } else {
        this.src = this.decodeCodePointsSpend(input);
        this.n = this.cps.length;
      }
    } else if (unit === Bytes) {
      this.bs = typeof input === "string" ? encodeUTF8(input) : input;
      this.n = this.bs.length;
      this.src = this.decodeBytes();
    } else if (typeof input === "string") {
      this.src = this.decodeString(input);
      this.n = this.cps.length;
    } else {
      this.src = this.decodeCodePoints(input);
      this.n = this.cps.length;
    }
    this.sparse = g.sparse && stride > 64 && this.n > 1024;
  }

  // decodeString sets cps (and offs) from s, with lone surrogates as U+FFFD, and returns s with the
  // same replacement.
  decodeString(s: string): string {
    const n = runeCount(s);
    const cps = new Int32Array(n);
    let offs: Int32Array | null = null;
    let lone = false;
    let j = 0;
    for (let i = 0; i < s.length; i++) {
      let c = s.charCodeAt(i);
      if (c >= 0xd800 && c <= 0xdfff) {
        if (c < 0xdc00 && i + 1 < s.length && (s.charCodeAt(i + 1) & 0xfc00) === 0xdc00) {
          if (offs === null) {
            offs = new Int32Array(n + 1);
            for (let k = 0; k < j; k++) {
              offs[k] = k;
            }
          }
          offs[j] = i;
          cps[j++] = 0x10000 + ((c - 0xd800) << 10) + (s.charCodeAt(i + 1) - 0xdc00);
          i++;
          continue;
        }
        c = 0xfffd;
        lone = true;
      }
      if (offs !== null) {
        offs[j] = i;
      }
      cps[j++] = c;
    }
    if (offs !== null) {
      offs[n] = s.length;
    }
    this.cps = cps;
    this.offs = offs;
    return lone ? wellFormed(s) : s;
  }

  // decodeCodePoints sets cps (and offs) by decoding b as Go does, and returns the text.
  decodeCodePoints(b: Uint8Array): string {
    const cps = new Int32Array(b.length);
    let j = 0;
    let astral = false;
    for (let i = 0; i < b.length; i += decodedSize) {
      const c = decodeRune(b, i, b.length);
      astral = astral || c > 0xffff;
      cps[j++] = c;
    }
    this.cps = cps.subarray(0, j);
    if (astral) {
      const offs = new Int32Array(j + 1);
      let o = 0;
      for (let k = 0; k < j; k++) {
        offs[k] = o;
        o += cps[k]! > 0xffff ? 2 : 1;
      }
      offs[j] = o;
      this.offs = offs;
    }
    return codePointsString(this.cps);
  }

  // decodeBytes sets offs from bs and returns the text, decoding bs as Go does. offs maps the
  // positions where a character starts (all positions a parse reaches) to offsets in the text.
  //
  // Text in byte mode holds bytes, as in Go, where text of invalid UTF-8 keeps the bytes: an invalid
  // byte b is the lone surrogate U+DC00+b in the text (U+DC80-U+DCFF, as Python's surrogateescape),
  // so that len, comparisons and toString see the bytes. JSON (marshal) writes it as U+FFFD, as Go
  // does.
  decodeBytes(): string {
    const b = this.bs;
    const n = b.length;
    let ascii = true;
    for (let i = 0; i < n; i++) {
      if (b[i]! >= 0x80) {
        ascii = false;
        break;
      }
    }
    const cps = new Int32Array(n);
    const offs = ascii ? null : new Int32Array(n + 1);
    let j = 0;
    let o = 0;
    for (let i = 0; i < n; i += decodedSize) {
      let c = decodeRune(b, i, n);
      if (decodedSize === 1 && c === 0xfffd) {
        c = 0xdc00 + b[i]!; // an invalid byte
      }
      if (offs !== null) {
        offs[i] = o;
      }
      o += c > 0xffff ? 2 : 1;
      cps[j++] = c;
    }
    if (offs !== null) {
      offs[n] = o;
    }
    this.offs = offs;
    return codePointsString(cps.subarray(0, j));
  }

  decodeStringSpend(s: string): string {
    const control = this.control!;
    const n = runeCountSpend(s, control);
    const cps = new Int32Array(n);
    let offs: Int32Array | null = null;
    let lone = false;
    let j = 0;
    for (let i = 0; i < s.length; i++) {
      let c = stringUnitSpend(s, i, control);
      if (c >= 0xd800 && c <= 0xdfff) {
        if (c < 0xdc00 && i + 1 < s.length && (stringUnitSpend(s, i + 1, control) & 0xfc00) === 0xdc00) {
          if (offs === null) {
            offs = new Int32Array(n + 1);
            for (let k = 0; k < j; k++) {
              control.charge(1);
              offs[k] = k;
            }
          }
          offs[j] = i;
          cps[j++] = 0x10000 + ((c - 0xd800) << 10) + (stringUnitSpend(s, i + 1, control) - 0xdc00);
          i++;
          continue;
        }
        c = 0xfffd;
        lone = true;
      }
      if (offs !== null) {
        offs[j] = i;
      }
      control.charge(1);
      cps[j++] = c;
    }
    if (offs !== null) {
      offs[n] = s.length;
    }
    this.cps = cps;
    this.offs = offs;
    return lone ? wellFormedSpend(s, control) : s;
  }

  decodeCodePointsSpend(b: Uint8Array): string {
    const control = this.control!;
    const cps = new Int32Array(b.length);
    let j = 0;
    let astral = false;
    for (let i = 0; i < b.length;) {
      const decoded = decodeRuneSpend(b, i, b.length, control);
      const c = decoded.rune;
      i += decoded.size;
      astral = astral || c > 0xffff;
      cps[j++] = c;
    }
    this.cps = cps.subarray(0, j);
    if (astral) {
      const offs = new Int32Array(j + 1);
      let o = 0;
      for (let k = 0; k < j; k++) {
        control.charge(1);
        offs[k] = o;
        o += cps[k]! > 0xffff ? 2 : 1;
      }
      offs[j] = o;
      this.offs = offs;
    }
    return codePointsStringSpend(this.cps, control);
  }

  decodeBytesSpend(): string {
    const control = this.control!;
    const b = this.bs;
    const n = b.length;
    let ascii = true;
    for (let i = 0; i < n; i++) {
      if (byteUnitSpend(b, i, n, control) >= 0x80) {
        ascii = false;
        break;
      }
    }
    const cps = new Int32Array(n);
    const offs = ascii ? null : new Int32Array(n + 1);
    let j = 0;
    let o = 0;
    for (let i = 0; i < n;) {
      const decoded = decodeRuneSpend(b, i, n, control);
      let c = decoded.rune;
      if (decoded.size === 1 && c === 0xfffd) {
        c = 0xdc00 + byteUnitSpend(b, i, n, control); // an invalid byte
      }
      if (offs !== null) {
        offs[i] = o;
      }
      o += c > 0xffff ? 2 : 1;
      control.charge(1);
      cps[j++] = c;
      i += decoded.size;
    }
    if (offs !== null) {
      offs[n] = o;
    }
    this.offs = offs;
    return codePointsStringSpend(cps.subarray(0, j), control);
  }


  // firstCall records a call of rule r at the current position and reports whether its
  // memoization is deferred: it is the first call there, and repeated calls of the rule have been
  // rare so far. Results are reused only when a rule is called again at a position, which is rare,
  // so memoizing every first call cost an entry each for nothing; deferring memoization to the
  // second call evaluates a rule at most twice per position, which keeps parse time linear.
  firstCall(r: Rule): boolean {
    if (r.seen < 0) {
      return false;
    }
    const s = r.seen;
    if (this.eager[s] !== 0) {
      return false;
    }
    // Discount old observations before the compact counters can wrap. Eager
    // mode is sticky; this estimator only chooses when to enter it.
    let calls = (this.calls[s]! + 1) >>> 0;
    if ((calls & 0x80000000) !== 0) {
      calls >>>= 1;
      this.repeats[s] = this.repeats[s]! >> 1;
    }
    this.calls[s] = calls;
    const first = this.sparse
      ? this.markSparseSeen(this.pos, s)
      : this.markSeen(this.pos, s);
    if (first) {
      return true;
    }
    // Deferring costs an extra evaluation for each position where the rule is called again, and
    // saves a memo entry for each position where it is not.
    this.repeats[s]!++;
    if (this.repeats[s]! > (calls >> 4)) {
      this.eager[s] = 1;
    }
    return false;
  }

  // memoGet returns the entry for the rule, position, level and variable values. A lookup walks the
  // first memoScan entries of the position's chain and then asks the position's hash index, so
  // it costs the size of its key and not the length of the chain.
  memoGet(rule: number, pos: number, min: number, env: Value[] | null): MemoEntry | null {
    let e = this.slots[pos] || null;
    for (let n = 0; e && n < memoScan; e = e.next, n++) {
      this.spend();
      if (e.rule === rule && e.min === min && sameValues(e.env, env, this.control)) {
        return e;
      }
    }
    if (!e) {
      return null;
    }
    const ix = this.memoIndexAt(pos);
    return this.memoProbe(ix, memoKeyHash(rule, min, env, this.control), (x) => x.rule === rule && x.min === min && sameValues(x.env, env, this.control));
  }

  /** memoIndex holds the hash index of each position whose chain has more than memoScan entries. */
  memoIndex: Map<number, Map<number, MemoEntry>> | null = null;
  /** memoSlot is the slot where the last memoProbe found its entry, or would store one. */
  memoSlot = 0;

  // memoProbe returns the entry that match accepts among the entries of ix at h and above, leaving
  // in memoSlot the slot where it is, or the free slot where it would be stored.
  memoProbe(ix: Map<number, MemoEntry>, h: number, match: (x: MemoEntry) => boolean): MemoEntry | null {
    for (let slot = h;; slot = (slot + 1) >>> 0) {
      const x = ix.get(slot);
      if (x === undefined || match(x)) {
        this.memoSlot = slot;
        return x === undefined ? null : x;
      }
    }
  }

  // memoIndexAt returns the hash index of the chain at pos, building it on first use.
  memoIndexAt(pos: number): Map<number, MemoEntry> {
    if (this.memoIndex === null) {
      this.memoIndex = new Map();
    }
    let ix = this.memoIndex.get(pos);
    if (ix === undefined) {
      ix = new Map();
      for (let e = this.slots[pos] || null; e; e = e.next) {
        this.memoProbe(ix, memoKeyHash(e.rule, e.min, e.env, this.control), () => false);
        ix.set(this.memoSlot, e);
      }
      this.memoIndex.set(pos, ix);
    }
    return ix;
  }

  // memoPut stores e under the key, replacing an entry with the same key.
  memoPut(rule: number, pos: number, min: number, env: Value[] | null, e: MemoEntry): void {
    e.rule = rule;
    e.min = min;
    e.env = env;
    const same = (x: MemoEntry): boolean => x === e || (x.rule === rule && x.min === min && sameValues(x.env, env, this.control));
    let prev: MemoEntry | null = null;
    let x = this.slots[pos] || null;
    let replaced: MemoEntry | null = null;
    for (let n = 0; x && n < memoScan; prev = x, x = x.next, n++) {
      this.spend();
      if (same(x)) {
        replaced = x;
        break;
      }
    }
    let ix: Map<number, MemoEntry> | undefined;
    let ixSlot = 0;
    if (replaced === null && x) {
      // A long chain: the index finds the entry to replace.
      ix = this.memoIndexAt(pos);
      replaced = this.memoProbe(ix, memoKeyHash(rule, min, env, this.control), same);
      ixSlot = this.memoSlot;
      if (replaced !== null) {
        prev = null;
        for (let y = this.slots[pos] || null; y !== replaced; prev = y, y = y!.next) {
          this.spend();
        }
      }
    } else if (replaced !== null) {
      // The entry replaced among the first of a long chain is indexed too.
      ix = this.memoIndex?.get(pos);
      if (ix !== undefined) {
        const r = replaced;
        this.memoProbe(ix, memoKeyHash(r.rule, r.min, r.env, this.control), (y) => y === r);
        ixSlot = this.memoSlot;
      }
    }
    if (ix !== undefined) {
      ix.set(ixSlot, e);
    }
    if (replaced !== null) {
      e.next = replaced.next;
      if (prev === null) {
        this.slots[pos] = e;
      } else {
        prev.next = e;
      }
      return;
    }
    if (this.slots.length === 0) {
      // One slot per position, allocated at once: writes far beyond the end of an array would
      // make it a slow dictionary.
      if (this.control === null) {
        this.slots = new Array(this.n + 1).fill(null);
      } else {
        const slots: (MemoEntry | null)[] = new Array(this.n + 1);
        for (let from = 0; from < slots.length; from += 128) {
          const end = Math.min(from + 128, slots.length);
          this.spend(end - from);
          slots.fill(null, from, end);
        }
        this.slots = slots;
      }
    }
    e.next = this.slots[pos] || null;
    this.slots[pos] = e;
  }

  // envValues returns the current values of the variables in slots (null for none).
  envValues(slots: number[]): Value[] | null {
    if (slots.length === 0) {
      return null;
    }
    const vals: Value[] = new Array(slots.length);
    for (let i = 0; i < slots.length; i++) {
      this.spend();
      vals[i] = this.variable(slots[i]!);
    }
    return vals;
  }

  // variable returns the value of the variable in slot i. Under budget controls it costs one
  // unit for each array on the path to the slot (the levels of the environment, and the leaf).
  variable(slot: number): Value {
    this.spend(this.envDepth + 1);
    return envGet(this.env!, slot, this.envDepth);
  }

  newFrame(n: number): Frame {
    if (n === 0) {
      return emptyFrame; // never written, so shared
    }
    const f: Frame = new Array(n);
    for (let i = 0; i < n; i++) {
      this.spend();
      f[i] = null;
    }
    return f;
  }

  // kids returns kidStack[base:] as a child list and pops it.
  kids(base: number): (Node | null)[] {
    const ks = this.control === null ? this.kidStack.slice(base) : copyNodesSpend(this.kidStack, base, this.kidStack.length, this.control);
    this.kidStack.length = base;
    return ks;
  }

  // dropKids pops kidStack[base:].
  dropKids(base: number): void {
    this.kidStack.length = base;
  }

  // reset returns to a mark: the position, variables, recovered errors and captures (undoing the
  // trail) at the time it was taken.
  reset(pos: number, env: Env | null, trail: number, recovered: number): void {
    this.pos = pos;
    this.env = env;
    this.recovered.length = recovered;
    for (let i = this.trail.length - 1; i >= trail; i--) {
      this.spend();
      const u = this.trail[i]!;
      u.f[u.slot] = u.old;
    }
    this.trail.length = trail;
  }

  setCapture(slot: number, v: Node | null): void {
    this.trail.push({ f: this.frame, slot, old: this.frame[slot]! });
    this.frame[slot] = v;
  }

  // peek returns the character at the current position (-1 at the end) and sets psize to its size
  // in units.
  peek(): number {
    const control = this.control;
    if (control !== null) {
      if (this.pos >= this.n) {
        control.charge(1); // EOF probes count, including repeated probes.
        return -1;
      }
      if (this.unit === Bytes) {
        const c = byteUnitSpend(this.bs, this.pos, this.n, control);
        if (c < 0x80) {
          this.psize = 1;
          return c;
        }
        const decoded = decodeRuneSpend(this.bs, this.pos, this.n, control);
        this.psize = decoded.size;
        return decoded.rune;
      }
      control.charge(1);
      this.psize = 1;
      return this.cps[this.pos]!;
    }
    if (this.pos >= this.n) {
      return -1;
    }
    if (this.unit === Bytes) {
      const c = this.bs[this.pos]!;
      if (c < 0x80) {
        this.psize = 1;
        return c;
      }
      const r = decodeRune(this.bs, this.pos, this.n);
      this.psize = decodedSize;
      return r;
    }
    this.psize = 1;
    return this.cps[this.pos]!;
  }

  unitLen(s: string): number {
    const control = this.control;
    if (control !== null) return this.unit === Bytes ? utf8LenSpend(s, control) : runeCountValueSpend(s, control);
    return this.unit === Bytes ? utf8Len(s) : runeCount(s);
  }

  // expect records that id was expected at pos.
  expect(pos: number, id: number): void {
    if (this.silent > 0 || pos < this.farthest) {
      return;
    }
    if (pos > this.farthest) {
      this.farthest = pos;
      this.expTop = this.expBase;
    }
    if (!this.expectations) {
      if (this.expTop === this.expBase) this.exp[this.expTop++] = expFar;
      return;
    }
    for (let i = this.expBase; i < this.expTop; i++) {
      this.spend();
      if (this.exp[i] === id) {
        return;
      }
    }
    this.exp[this.expTop++] = id;
  }

  // keep copies exp[from:to] for a memo entry or a recovery.
  keep(from: number, to: number): number[] {
    if (from === to) {
      return noExp;
    }
    const last = this.lastKept;
    if (last.length === to - from) {
      let same = true;
      for (let i = 0; i < last.length; i++) {
        this.spend();
        if (last[i] !== this.exp[from + i]) {
          same = false;
          break;
        }
      }
      if (same) {
        return last; // the same set often repeats
      }
    }
    this.lastKept = this.control === null ? this.exp.slice(from, to) : copyIDsSpend(this.exp, from, to, this.control);
    return this.lastKept;
  }

  // mergeExpected records the expectations exp[from:to] at far. They may lie above the current
  // record (writes only happen below the read position).
  mergeExpected(far: number, from: number, to: number): void {
    for (let i = from; i < to; i++) {
      this.spend();
      this.expect(far, this.exp[i]!);
    }
  }

  // isolate begins a separate record of the expectations from the position and returns its mark,
  // for unisolate.
  isolate(): number {
    const mk = this.isoStack.length;
    this.isoStack.push(this.farthest, this.expBase);
    this.expBase = this.expTop;
    this.farthest = this.pos;
    return mk;
  }

  // unisolate ends the record that isolate began, returns the farthest position it reached and
  // leaves a copy of its expectations in isoIds.
  unisolate(mk: number): number {
    const far = this.farthest;
    const from = this.expBase;
    const to = this.expTop;
    if (from === to) {
      this.isoIds = noExp;
    } else {
      this.isoIds = this.control === null ? this.exp.slice(from, to) : copyIDsSpend(this.exp, from, to, this.control);
    }
    this.expTop = from;
    this.expBase = this.isoStack[mk + 1]!;
    this.farthest = this.isoStack[mk]!;
    this.isoStack.length = mk;
    return far;
  }

  // unisolateMerge ends the record that isolate began and merges its expectations into the enclosing
  // record in place, which unisolate and mergeKept do with a copy.
  unisolateMerge(mk: number): void {
    const far = this.farthest;
    const from = this.expBase;
    const to = this.expTop;
    this.expTop = from;
    this.expBase = this.isoStack[mk + 1]!;
    this.farthest = this.isoStack[mk]!;
    this.isoStack.length = mk;
    this.mergeExpected(far, from, to);
  }

  // renameExpected returns ids with the expectations that are not messages renamed to name.
  renameExpected(ids: number[], name: number): number[] {
    const out: number[] = [];
    for (const id of ids) {
      this.spend();
      out.push((id & msgBit) !== 0 ? id : name);
    }
    return out;
  }

  mergeKept(far: number, ids: number[]): void {
    for (const x of ids) {
      this.spend();
      this.expect(far, x);
    }
  }

  // Skip runs, a mirror of the Go runtime's (runtime/skip_runs.go; see "Skip Runs" in
  // spec/runtime/parsing.md). A walk of a skip-run site visits positions with one iteration each.
  // It starts plain, marking the position of each iteration that matched (so a walk that fails at
  // once touches no slot; skipPrev is the position of the last iteration, or -1), and starts
  // recording at its first position
  // that is not fresh: from there on it records, for each visited position, what the rest of the
  // walk from there did, filling the records backward when it ends. A recording walk that reaches a
  // recorded position (once it has matched its minimum) takes the rest from the record, as a memo
  // hit does. The slots of a parse last for that parse.

  // skipBegin starts a walk of the site at the current position.
  skipBegin(site: number): void {
    const i = 2 * site + (this.silent > 0 ? 1 : 0);
    this.skipTable = i;
    this.skipSlots = this.skipTables[i];
    this.skipPrev = -1;
    this.skipVisits.length = 0;
    this.skipRecording = false;
    this.skipOpen = false;
    this.skipHitRec = null;
  }

  // skipRecords reports whether the walk records from the current position on, which it starts to
  // at the first position that is not fresh.
  skipRecords(): boolean {
    if (!this.skipRecording && this.skipSlots !== undefined && this.skipSlots.marked(this.pos)) {
      this.skipMarkPrev();
      this.skipRecording = true;
    }
    return this.skipRecording;
  }

  // skipMarkPrev marks the position of the last iteration of a plain walk, which matched.
  skipMarkPrev(): void {
    if (this.skipPrev >= 0) {
      this.skipSlot(this.skipPrev, null);
      this.skipPrev = -1;
    }
  }

  // skipHit is called before an iteration after the minimum. It ends the iteration before and, in a
  // recording walk, reports whether the current position has a record, which it then reuses. The
  // walk then stops.
  skipHit(): boolean {
    if (!this.skipRecords()) {
      return false;
    }
    this.skipClose();
    this.spend();
    const r = this.skipSlots?.recs.get(this.pos);
    if (r === undefined) {
      return false;
    }
    this.spend();
    this.mergeKept(r.far, r.exp);
    this.pos = r.end;
    this.skipHitRec = r;
    return true;
  }

  // skipVisit begins an iteration at the current position: in a plain walk it marks the position of
  // the iteration before, which matched, visited; in a recording walk it ends the iteration before
  // and isolates this one.
  skipVisit(): void {
    if (!this.skipRecords()) {
      this.skipMarkPrev();
      this.skipPrev = this.pos;
      return;
    }
    this.skipClose();
    this.skipVisits.push({ pos: this.pos, far: 0, exp: noExp });
    this.skipOpen = true;
    this.skipFar = this.farthest;
    this.skipBase = this.expBase;
    this.expBase = this.expTop;
    this.farthest = this.pos;
  }

  // skipClose ends the running iteration, if any: it keeps its expectations and records them as
  // usual.
  skipClose(): void {
    if (!this.skipOpen) {
      return;
    }
    this.skipOpen = false;
    const far = this.farthest;
    const from = this.expBase;
    const to = this.expTop;
    this.expTop = this.expBase;
    this.expBase = this.skipBase;
    this.farthest = this.skipFar;
    const v = this.skipVisits[this.skipVisits.length - 1]!;
    v.far = far;
    v.exp = this.keep(from, to);
    this.mergeExpected(far, from, to);
  }

  // skipEnd ends the walk and records the rest of it from each position it visited recording.
  skipEnd(): void {
    this.skipClose();
    const vs = this.skipVisits;
    let n = vs.length;
    let next = this.skipHitRec;
    if (next === null && n > 0) {
      // The last iteration failed or matched nothing: the walk ended at its start.
      const v = vs[--n]!;
      next = { end: v.pos, far: v.far, exp: v.exp };
      this.skipPut(v.pos, next);
    }
    for (let i = n - 1; i >= 0; i--) {
      const v = vs[i]!;
      const r: SkipRecord = { end: next!.end, far: next!.far, exp: next!.exp };
      if (v.far > r.far) {
        r.far = v.far;
        r.exp = v.exp;
      } else if (v.far === r.far) {
        r.exp = mergeSkipExpected(v.exp, r.exp);
      }
      this.skipPut(v.pos, r);
      next = r;
    }
    vs.length = 0;
    this.skipHitRec = null;
  }

  // skipPut stores the record r of the position pos in the slots of the walk.
  skipPut(pos: number, r: SkipRecord): void {
    this.spend();
    this.skipSlot(pos, r);
  }

  // skipSlot sets the slot of pos in the slots of the walk, making them.
  skipSlot(pos: number, r: SkipRecord | null): void {
    let s = this.skipSlots;
    if (s === undefined) {
      s = new SkipSlots();
      this.skipSlots = s;
      this.skipTables[this.skipTable] = s;
    }
    s.put(pos, r);
  }

  // text returns the text of [start, end): a range of the input, which costs a constant whatever
  // its length (the string the slice builds is not part of the parse cost).
  text(start: number, end: number): string {
    const control = this.control;
    if (control !== null) {
      control.charge(1);
    }
    if (this.offs === null) {
      return this.src.slice(start, end);
    }
    return this.src.slice(this.offs[start], this.offs[end]);
  }

  // recoveredError is makeError for an error that #recover records and never throws: it leaves out the
  // stack trace, which costs more than the rest of the recovery and keeps the caller's frames alive.
  recoveredError(pos: number, expected: number[]): SyntaxError {
    return this.makeError(pos, expected, true);
  }

  makeError(pos: number, expected: number[], bare = false): SyntaxError {
    const exp: string[] = [];
    const msgs: string[] = [];
    for (const x of expected) {
      this.spend();
      if (x === expFar) continue;
      if ((x & msgBit) !== 0) {
        msgs.push(this.g.descs[x & ~msgBit]!);
      } else {
        exp.push(this.g.descs[x]!);
      }
    }
    if (this.control === null) exp.sort(compareExpected);
    else sortExpectedSpend(exp, this.control);
    // Look the line up in a table of line starts, built on the first error, instead of scanning
    // from the start of the input for each error.
    if (this.lines === null) {
      const lines = [0];
      const units = this.unit === Bytes ? this.bs : this.cps;
      for (let i = 0; i < this.n; i++) {
        this.control?.charge(1);
        if (units[i] === 0x0a) {
          lines.push(i + 1);
        }
      }
      this.lines = lines;
    }
    pos = Math.min(pos, this.n);
    // The number of line starts at or before pos.
    let lo = 0;
    let hi = this.lines.length;
    while (lo < hi) {
      this.spend();
      const mid = (lo + hi) >>> 1;
      if (this.lines[mid]! < pos + 1) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    const col = pos - this.lines[lo - 1]! + 1;
    if (this.control !== null) reserveSyntaxMessageSpend(lo, col, exp, msgs, this.control);
    const error = bare ? bareSyntaxError(pos, lo, col, exp, msgs) : new SyntaxError(pos, lo, col, exp, msgs);
    this.control?.check();
    return error;
  }

  markSeen(pos: number, s: number): boolean {
    const i = pos * this.stride + s;
    const w = Math.floor(i / 32);
    const bit = 1 << i % 32;
    if (w >= this.seen.length) {
      const grown = new Int32Array(Math.max(w + 1, 2 * this.seen.length, 64));
      if (this.control === null) {
        grown.set(this.seen);
      } else {
        for (let from = 0; from < this.seen.length; from += 128) {
          const end = Math.min(from + 128, this.seen.length);
          this.spend(end - from);
          grown.set(this.seen.subarray(from, end), from);
        }
      }
      this.seen = grown;
    }
    if ((this.seen[w]! & bit) === 0) {
      this.seen[w]! |= bit;
      return true;
    }
    return false;
  }

  // Page directories hold integer arena offsets, avoiding one typed-array
  // object per page. Chunks contain 64 pages of 1,024 position bits each.
  markSparseSeen(pos: number, s: number): boolean {
    this.spend();
    if (this.seenPages === null) {
      this.seenPages = [];
      this.seenPageChunks = [];
    }
    let pages = this.seenPages[s];
    if (pages === undefined) {
      this.spend();
      pages = [];
      this.seenPages[s] = pages;
    }
    const at = Math.floor(pos / 1024);
    let page = pages[at];
    if (page === undefined) {
      this.spend();
      page = this.seenPageCount++;
      if (page % 64 === 0) {
        this.seenPageChunks!.push(new Int32Array(64 * 32));
      }
      pages[at] = page;
    }
    const chunk = this.seenPageChunks![Math.floor(page / 64)]!;
    const word = (page % 64) * 32 + Math.floor((pos % 1024) / 32);
    const bit = 1 << (pos % 32);
    if ((chunk[word]! & bit) !== 0) {
      return false;
    }
    chunk[word]! |= bit;
    return true;
  }

  // --- Rule calls ---

  // call calls rule r at level min.
  call(r: Rule, min: number): R {
    const o = this.observation;
    if (o === null) return this.callBody(r, min);
    o.enter(r.name, this.pos, min);
    const v = this.callBody(r, min);
    o.exit(v !== undefined, this.pos);
    return v;
  }

  // callBody calls rule r at binding level min: unmemoized while its memoization is deferred, and
  // otherwise through the memo and the dependency memo of left-recursion contexts, growing the seed of
  // a left-recursion leader.
  callBody(r: Rule, min: number): R {
    let v: R = null;
    this.spend();
    const start = this.pos;
    if (!r.memo && !r.leader || this.firstCall(r)) {
      // Unmemoized call: no memo bookkeeping, and expectations need no isolation.
      if (r.scope.length === 0) {
        v = this.invokePlainBody(r, min);
        return v;
      }
      const rec = this.recovered.length;
      v = this.invoke(r, min);
      if (v === undefined) {
        this.pos = start;
        this.recovered.length = rec;
      }
      return v;
    }
    const env = this.envValues(r.vars);
    // The context of the call: the growths of the rule's cycle at the position, and the seed of the
    // rule's own growth there, which the call reads.
    let c = noCtx;
    let seed: CtxResult | null = null;
    if (r.cycle !== 0 && this.gamma.length !== 0) {
      c = newCtxCall();
      seed = this.ctxEnter(c, r, min);
    }
    if (seed !== null) {
      this.replayCtx(seed!, true);
      if (!seed!.ok) {
        return undefined;
      }
      return seed!.node;
    }
    // See the engine's callBegin: entries with recovered errors are reused only in the same kind of
    // context (inside or outside a lookahead) they were computed in.
    const e = this.memoGet(r.id, start, min, env);
    const found = e !== null;
    if (found && memoAllows(c, e.present) && ((!e.silent || this.silent > 0) && ((e.errs.length === 0) || e.silent === this.silent > 0))) {
      this.observation?.memoHit();
      this.mergeKept(e.far, e.expected);
      if (!e.ok) {
        return undefined;
      }
      this.pos = e.end;
      for (const x of e.errs) {
        this.spend();
        this.recovered.push(x);
      }
      return e.node;
    }
    if (c.ctx) {
      const held = this.ctxLookup(c, r.id, min, env);
      if (held !== null) {
        this.replayCtx(held!, false);
        if (!held!.ok) {
          return undefined;
        }
        return held!.node;
      }
    }
    const rec = this.recovered.length;
    this.ctxPush(c);
    // The memoized result includes the expectations recorded in this call.
    const mFar = this.farthest;
    const mBase = this.expBase;
    this.expBase = this.expTop;
    this.farthest = start;
    if (r.leader) {
      v = this.grow(r, min);
    } else {
      v = this.invoke(r, min);
      if (v === undefined) {
        this.recovered.length = rec;
      }
    }
    const far = this.farthest;
    const innerFrom = this.expBase;
    const innerTo = this.expTop;
    this.expTop = this.expBase;
    this.expBase = mBase;
    this.farthest = mFar;
    const kept = this.keep(innerFrom, innerTo);
    // The result goes to the memo, or to the table of its context if it read a seed or observed a
    // lookahead that did.
    const store = this.ctxPop(c);
    if (store === storeMemo) {
      const entry = newEntry(v, v !== undefined, this.pos, this.silent > 0, this.recovered.length > rec ? (this.control === null ? this.recovered.slice(rec) : copyErrorsSpend(this.recovered, rec, this.recovered.length, this.control)) : noErrs);
      this.memoPut(r.id, start, min, env, entry);
      entry.present = c.present;
      entry.far = far;
      entry.expected = kept;
    } else if (store === storeCtx) {
      this.ctxKeep(c, r.id, start, min, env, newCtxResult(v, this.pos, this.silent > 0, this.recovered.length > rec ? (this.control === null ? this.recovered.slice(rec) : copyErrorsSpend(this.recovered, rec, this.recovered.length, this.control)) : noErrs, far, kept));
    }
    this.ctxDone(c);
    this.mergeExpected(far, innerFrom, innerTo);
    if (v === undefined) {
      this.pos = start;
    }
    return v;
  }

  // grow grows the seed of a left-recursive leader from a failure: it evaluates the body again while
  // the match gets longer, and returns the last longer result.
  grow(r: Rule, min: number): R {
    const g = this.growBegin(r, min);
    for (;;) {
      if (!this.growNext(g)) {
        break;
      }
      const v = this.invoke(r, min);
      this.growStep(g, v);
    }
    const best = this.growEnd(g);
    return best!.ok ? best!.node : undefined;
  }

  // --- The dependency memo of left recursion ---
  //
  // A mirror of the Go runtime's (runtime/context_memo.go; see "Evaluations of Rules" in
  // spec/runtime/parsing.md and spec/proofs/memoization.md), without Documents: the examined input
  // of results is not tracked.

  // recSince returns a copy of the errors recovered since rec.
  recSince(rec: number): SyntaxError[] {
    return this.recovered.length > rec ? (this.control === null ? this.recovered.slice(rec) : copyErrorsSpend(this.recovered, rec, this.recovered.length, this.control)) : noErrs;
  }

  // gammaAt returns the index of the first growth of the cycle at pos that the innermost growths
  // there are (gamma.length if the innermost growth is not one).
  gammaAt(pos: number, cycle: number): number {
    let i = this.gamma.length;
    while (i > 0 && this.gamma[i - 1]!.pos === pos && this.gamma[i - 1]!.cycle === cycle) {
      i--;
    }
    return i;
  }

  // gammaFind returns the index of the growth of the leader rule at level min from gp on, or -1.
  gammaFind(gp: number, rule: number, min: number): number {
    for (let i = this.gamma.length - 1; i >= gp; i--) {
      const g = this.gamma[i]!;
      if (g.rule === rule && g.min === min) {
        return i;
      }
    }
    return -1;
  }

  // presentOf returns the present set of the context gamma[gp:], or null if a leader in it has no
  // bit.
  presentOf(gp: number): number | null {
    let m = 0;
    for (let i = gp; i < this.gamma.length; i++) {
      const b = this.gamma[i]!.bit;
      if (b === 0) {
        return null;
      }
      m |= b;
    }
    return m;
  }

  // ctxEnter computes the context c of a memoized call of r, a rule of a cycle, at the current
  // position and level min. When r is a leader that grows there, it returns the seed, which the call
  // reads whatever its variable values.
  ctxEnter(c: CtxCall, r: Rule, min: number): CtxResult | null {
    const gp = this.gammaAt(this.pos, r.cycle);
    c.gp = gp;
    if (gp === this.gamma.length) {
      return null;
    }
    if (r.leader) {
      const i = this.gammaFind(gp, r.id, min);
      if (i >= 0) {
        this.noteSeedRead(i);
        return this.gamma[i]!.seed;
      }
    }
    c.ctx = true;
    const present = this.presentOf(gp);
    if (present !== null) {
      c.present = present;
      c.known = true;
    }
    return null;
  }

  // ctxLookup returns the result kept in the context c for a call of rule at level min with the
  // variable values env, or null.
  ctxLookup(c: CtxCall, rule: number, min: number, env: Value[] | null): CtxResult | null {
    if (!c.known) {
      return null;
    }
    const s = this.ctxFind(this.pos, c.gp, headKey(ctxCallKind, rule, min, c.present), c.present, env);
    if (s === null || !this.reusable(s.e!.silent, s.e!.errs.length)) {
      return null;
    }
    this.replayDeps(this.pos, c.gp, c.present, s.deps);
    return s.e;
  }

  // ctxPush starts recording the dependencies of a call in the context c.
  ctxPush(c: CtxCall): void {
    if (c.known) {
      this.pushFrame(this.pos, c.gp);
      c.framed = true;
    }
  }

  // ctxPop ends the dependencies of a call in the context c and returns how the call stores its
  // result: in the table of the context if it read a seed or made an observation, and otherwise in
  // the memo. The dependencies stay readable for ctxKeep until ctxDone.
  ctxPop(c: CtxCall): number {
    if (c.framed) {
      this.popped = this.popFrame().deps;
      for (const d of this.popped) {
        if (d.kind !== depShadow) {
          return storeCtx;
        }
      }
      return storeMemo;
    }
    if (c.ctx) {
      return storeNone;
    }
    return storeMemo;
  }

  // ctxKeep keeps the result res of a call of rule at start and level min with the variable values
  // env in the table of the context c, with the dependencies that ctxPop ended.
  ctxKeep(c: CtxCall, rule: number, start: number, min: number, env: Value[] | null, res: CtxResult): void {
    const sd = this.stored(this.popped);
    this.ctxStore(start, c.gp, headKey(ctxCallKind, rule, min, c.present), sd, newSlot(res, 0, env));
  }

  // ctxDone passes the dependencies that ctxPop ended to the enclosing frame.
  ctxDone(c: CtxCall): void {
    if (c.framed) {
      this.mergeDeps(this.popped);
      this.popped = noDeps;
    }
  }

  // pushFrame starts recording the dependencies of an evaluation at pos, in the context of the
  // growths gamma[gp:] there.
  pushFrame(pos: number, gp: number): void {
    this.depFrames.push({ pos, gp, depth: this.gamma.length, base: this.deps.length });
  }

  // popFrame ends the innermost frame and returns it with its dependencies.
  popFrame(): { f: DepFrame; deps: Dep[] } {
    const f = this.depFrames.pop()!;
    return { f, deps: this.deps.length > f.base ? this.deps.splice(f.base) : noDeps };
  }

  // addDep adds d to the innermost frame unless it holds it already.
  addDep(d: Dep): void {
    const f = this.depFrames[this.depFrames.length - 1]!;
    for (let i = f.base; i < this.deps.length; i++) {
      const x = this.deps[i]!;
      if (x.kind === d.kind && x.idx === d.idx && (d.kind !== depObs || x.d === d.d)) {
        return;
      }
    }
    this.spend();
    this.deps.push(d);
  }

  // mergeDeps passes the dependencies of a finished evaluation to the innermost frame: the seeds of
  // its context, and the observations made in the same context. A shadow becomes a seed read when
  // the frame cannot check the observation it belongs to.
  mergeDeps(ds: Dep[]): void {
    if (this.depFrames.length === 0) {
      return;
    }
    const depth = this.depFrames[this.depFrames.length - 1]!.depth;
    for (const d of ds) {
      switch (d.kind) {
        case depSeed:
          if (d.idx < depth) this.addDep(d);
          break;
        case depObs:
          if (d.d === depth) this.addDep(d);
          break;
        case depShadow:
          if (d.d === depth) {
            this.addDep(d);
          } else if (d.idx < depth) {
            this.addDep({ kind: depSeed, idx: d.idx, d: 0, val: d.val });
          }
          break;
      }
    }
  }

  // noteSeedRead records that the evaluation read the seed of gamma[i].
  noteSeedRead(i: number): void {
    const n = this.depFrames.length;
    if (n === 0 || i >= this.depFrames[n - 1]!.depth) {
      return;
    }
    this.addDep({ kind: depSeed, idx: i, d: 0, val: this.gamma[i]!.id });
  }

  // stored converts frame dependencies to stored ones.
  stored(ds: Dep[]): Sdep[] {
    if (ds.length === 0) {
      return noSdeps;
    }
    const out: Sdep[] = [];
    for (const d of ds) {
      this.spend();
      if (d.kind === depObs) {
        out.push({ kind: depObs, rule: 0, min: 0, site: d.idx, val: d.val });
      } else {
        const g = this.gamma[d.idx]!;
        out.push({ kind: d.kind, rule: g.rule, min: g.min, site: 0, val: d.val });
      }
    }
    return out;
  }

  // replayDeps passes the stored dependencies of a reused result at pos, whose present set is
  // present, to the innermost frame, as if the evaluation that produced them had run in the current
  // context gamma[gp:]: the seeds it read with their current identities, and each observation with
  // the seeds that its outcome read in the current context (replayObs) as well as those it read
  // where it was made. A frame that cannot check an observation depends on those seeds instead.
  replayDeps(pos: number, gp: number, present: number, ds: Sdep[]): void {
    if (this.depFrames.length === 0 || ds.length === 0) {
      return;
    }
    const depth = this.gamma.length;
    const buf: Dep[] = [];
    for (const d of ds) {
      if (d.kind === depObs) {
        buf.push({ kind: depObs, idx: d.site, d: depth, val: d.val });
        this.replayObs(buf, pos, gp, present, d.site, depth);
      } else {
        const i = this.gammaFind(gp, d.rule, d.min);
        if (i < 0) {
          continue;
        }
        buf.push({ kind: d.kind, idx: i, d: depth, val: this.gamma[i]!.id });
      }
    }
    this.mergeDeps(buf);
  }

  // replayObs appends to buf the shadows of the seeds that the outcome memoized for the lookahead
  // site at pos in the current context read, and the observations it depends on with their shadows.
  replayObs(buf: Dep[], pos: number, gp: number, present: number, site: number, depth: number): void {
    for (const s of this.obsGuard) {
      if (s === site) {
        return;
      }
    }
    this.obsGuard.push(site);
    try {
      const s = this.ctxFind(pos, gp, headKey(ctxLookKind, site, 0, present), present, null);
      if (s === null) {
        return;
      }
      const set = this.foundSet!;
      for (let j = 0; j < set.seeds.length; j += 2) {
        const i = this.gammaFind(gp, set.seeds[j]!, set.seeds[j + 1]!);
        if (i >= 0) {
          buf.push({ kind: depShadow, idx: i, d: depth, val: this.gamma[i]!.id });
        }
      }
      for (const o of set.obs) {
        const v = this.obsValue(pos, gp, present, o);
        if (v !== obsNone) {
          buf.push({ kind: depObs, idx: o, d: depth, val: v });
          this.replayObs(buf, pos, gp, present, o, depth);
        }
      }
    } finally {
      this.obsGuard.pop();
    }
  }

  // table returns the table of the growths gamma[gp:] at pos, creating it if create is set, or null.
  table(pos: number, gp: number, create: boolean): CtxTable | null {
    const n = this.ctxs.length;
    if (n > 0 && this.ctxs[n - 1]!.pos === pos && this.ctxs[n - 1]!.depth === gp) {
      return this.ctxs[n - 1]!;
    }
    if (!create) {
      return null;
    }
    const t: CtxTable = { pos, depth: gp, heads: new Map(), jumps: null, canon: null };
    this.ctxs.push(t);
    return t;
  }

  // dropTable drops the table of the growth at gamma[i] if that growth is the first of its context.
  dropTable(i: number): void {
    const n = this.ctxs.length;
    if (n > 0 && this.ctxs[n - 1]!.pos === this.gamma[i]!.pos && this.ctxs[n - 1]!.depth === i) {
      this.ctxs.pop();
    }
  }

  // obsValue returns the outcome memoized for the lookahead site at pos in the current context, or
  // obsNone.
  obsValue(pos: number, gp: number, present: number, site: number): number {
    for (const s of this.obsGuard) {
      if (s === site) {
        return obsNone;
      }
    }
    this.obsGuard.push(site);
    try {
      const s = this.ctxFind(pos, gp, headKey(ctxLookKind, site, 0, present), present, null);
      return s === null ? obsNone : s.id;
    } finally {
      this.obsGuard.pop();
    }
  }

  // obsFree returns the outcome memoized for the lookahead site at pos in the current context, or
  // obsNone, and whether it was obtained without reading the seed of the growth g, directly or
  // through the observations it depends on. Such an outcome is the outcome of the lookahead for every
  // seed of g: an evaluation follows the same path, and reads the same seeds, as long as the seeds
  // it reads are equal.
  obsFree(pos: number, gp: number, present: number, site: number, g: GrowState): { v: number; free: boolean } {
    for (const s of this.obsGuard) {
      if (s === site) {
        return { v: obsNone, free: false };
      }
    }
    this.obsGuard.push(site);
    try {
      const s = this.ctxFind(pos, gp, headKey(ctxLookKind, site, 0, present), present, null);
      if (s === null) {
        return { v: obsNone, free: false };
      }
      const set = this.foundSet!;
      for (let j = 0; j < set.seeds.length; j += 2) {
        if (set.seeds[j] === g.rule && set.seeds[j + 1] === g.min) {
          return { v: s.id, free: false };
        }
      }
      for (const o of set.obs) {
        if (!this.obsFree(pos, gp, present, o, g).free) {
          return { v: s.id, free: false };
        }
      }
      return { v: s.id, free: true };
    } finally {
      this.obsGuard.pop();
    }
  }

  // ctxFind looks up a result of head h, whose present set is present, in the table of the growths
  // gamma[gp:] at pos for the current context, and leaves its set in foundSet.
  ctxFind(pos: number, gp: number, h: string, present: number, env: Value[] | null): CtxSlot | null {
    const t = this.table(pos, gp, false);
    if (t === null) {
      return null;
    }
    this.spend();
    const sets = t.heads.get(h);
    if (sets === undefined) {
      return null;
    }
    next: for (const s of sets) {
      this.spend();
      let k = "";
      for (let j = 0; j < s.seeds.length; j += 2) {
        const i = this.gammaFind(gp, s.seeds[j]!, s.seeds[j + 1]!);
        if (i < 0) {
          continue next;
        }
        k += this.gamma[i]!.id + ",";
      }
      for (const o of s.obs) {
        const v = this.obsValue(pos, gp, present, o);
        if (v === obsNone) {
          continue next;
        }
        k += v + ",";
      }
      for (let x: CtxSlot | null = s.vals.get(k) ?? null; x !== null; x = x.next) {
        this.spend();
        if (env === null && x.env === null || sameValues(x.env, env, this.control)) {
          this.foundSet = s;
          return x;
        }
      }
    }
    return null;
  }

  // ctxStore stores slot as the result of head h in the table of the growths gamma[gp:] at pos, with
  // the stored dependencies ds.
  ctxStore(pos: number, gp: number, h: string, ds: Sdep[], slot: CtxSlot): void {
    const seeds: number[] = [];
    const obs: number[] = [];
    for (const d of ds) {
      if (d.kind === depShadow) {
        continue;
      }
      if (seeds.length / 2 + obs.length === maxCtxDeps) {
        return; // too many dependencies to index: the result is evaluated again
      }
      if (d.kind === depSeed) {
        seeds.push(d.rule, d.min);
      } else {
        obs.push(d.site);
      }
    }
    // The values follow the order of the set: seeds first, then observations.
    let k = "";
    for (const d of ds) {
      if (d.kind === depSeed) k += d.val + ",";
    }
    for (const d of ds) {
      if (d.kind === depObs) k += d.val + ",";
    }
    const t = this.table(pos, gp, true)!;
    this.spend();
    let sets = t.heads.get(h);
    if (sets === undefined) {
      sets = [];
      t.heads.set(h, sets);
    }
    let set: CtxSet | null = null;
    for (const s of sets) {
      this.spend();
      if (sameNumbers(s.seeds, seeds) && sameNumbers(s.obs, obs)) {
        set = s;
        break;
      }
    }
    if (set === null) {
      set = { seeds, obs, vals: new Map() };
      sets.push(set);
    }
    slot.deps = ds;
    const link = set.vals.get(k) ?? null;
    for (let x = link; x !== null; x = x.next) {
      this.spend();
      if (x.env === null && slot.env === null || sameValues(x.env, slot.env, this.control)) {
        // Replace the result in place: the other kind of context (inside or outside a lookahead)
        // evaluated it again.
        const nx = x.next;
        Object.assign(x, slot);
        x.next = nx;
        return;
      }
    }
    slot.next = link;
    set.vals.set(k, slot);
  }

  // reusable reports whether a memoized result evaluated inside a lookahead (silent) or with
  // recovered errors can be used by a call in the current kind of context, as for memo entries.
  reusable(silent: boolean, errs: number): boolean {
    return (!silent || this.silent > 0) && (errs === 0 || silent === this.silent > 0);
  }

  // replayCtx applies a result that a context kept, or a seed (seed), as the call that it records
  // would have.
  replayCtx(e: CtxResult, seed: boolean): void {
    this.observation?.memoHit();
    if (!seed) {
      this.mergeKept(e.far, e.expected);
    }
    if (e.ok) {
      this.pos = e.end;
      for (const x of e.errs) {
        this.spend();
        this.recovered.push(x);
      }
    }
  }

  // lookBegin starts a lookahead of the given site. In a context at the current position, the
  // lookahead records what it reads, so that a result that depends on it records its outcome
  // instead of the seeds it read (lookEnd). Where no frame records dependencies, a lookahead records
  // nothing, and the frames are the same at its end.
  lookBegin(site: number): void {
    const n = this.depFrames.length;
    if (n === 0) {
      return;
    }
    const f = this.depFrames[n - 1]!;
    const g = this.gamma.length;
    if (f.pos === this.pos && f.gp < g && this.gamma[g - 1]!.pos === this.pos && this.gamma[g - 1]!.cycle === this.gamma[f.gp]!.cycle) {
      this.looks.push(site);
      this.lookRecs.push(this.recovered.length);
      this.pushFrame(this.pos, f.gp);
      return;
    }
    this.looks.push(-1);
    this.lookRecs.push(0);
  }

  // lookEnd ends the innermost lookahead, whose expression matched if ok.
  lookEnd(ok: boolean): void {
    if (this.depFrames.length === 0) {
      return;
    }
    const site = this.looks.pop()!;
    const rec = this.lookRecs.pop()!;
    if (site < 0) {
      return;
    }
    const { f, deps: ds } = this.popFrame();
    let read = false;
    for (const d of ds) {
      if (d.kind === depSeed) {
        read = true;
        break;
      }
    }
    if (!read || (ok && this.recovered.length > rec)) {
      // Errors recovered in a matching lookahead stay recorded after it, so its outcome does not
      // summarize it: the seeds it read stay dependencies.
      this.mergeDeps(ds);
      return;
    }
    // Without Documents, the outcome is whether the expression matched.
    const val = ok ? 1 : 0;
    const present = this.presentOf(f.gp);
    const sd = this.stored(ds);
    if (present !== null) {
      this.ctxStore(f.pos, f.gp, headKey(ctxLookKind, site, 0, present), sd, newSlot(null, val, null));
    }
    const out: Dep[] = [{ kind: depObs, idx: site, d: f.depth, val }];
    for (const d of ds) {
      out.push(d.kind === depSeed ? { kind: depShadow, idx: d.idx, d: f.depth, val: d.val } : d);
    }
    this.mergeDeps(out);
  }

  // growBegin starts the growth of the leader r at level min at the current position from a failure.
  // A growth in a context, where another leader of its cycle grows, memoizes its steps (growNext).
  growBegin(r: Rule, min: number): GrowState {
    // One budget unit before each evaluation of the body, the seed's included.
    this.spend();
    const start = this.pos;
    const gi = this.gamma.length;
    const gp = this.gammaAt(start, r.cycle);
    const g: GrowState = { rule: r.id, min, start, rec: this.recovered.length, gi, gp, ctx: false, present: 0, done: false, exp: 0, run: [] };
    this.gamma.push({ rule: r.id, min, pos: start, cycle: r.cycle, bit: r.leaderBit, seed: newCtxResult(undefined, start, false, noErrs, 0, noExp), id: failSeed });
    if (gp < gi) {
      // The present set of the steps includes the leader's own growth.
      const present = this.presentOf(gp);
      if (present !== null) {
        g.present = present;
        g.ctx = true;
      }
    }
    return g;
  }

  // growNext reports whether the body must be evaluated for the next step. In a context it first
  // takes the steps it can from the jumps and the memoized steps.
  growNext(g: GrowState): boolean {
    if (g.done) {
      return false;
    }
    if (!g.ctx) {
      return true;
    }
    for (;;) {
      const id = this.gamma[g.gi]!.id;
      const j = this.findJump(g, id);
      if (j !== null) {
        this.replayDeps(g.start, g.gp, g.present, j.deps);
        this.mergeKept(j.far, j.exp);
        this.setSeed(g, j.end, j.id);
        continue;
      }
      const s = this.ctxFind(g.start, g.gp, headKey(ctxStepKind, g.rule, g.min, g.present), g.present, null);
      if (s !== null && this.reusable(s.silent, s.e!.errs.length)) {
        this.replayDeps(g.start, g.gp, g.present, s.deps);
        this.mergeKept(s.far, s.exp);
        if (!this.advance(g, s.e!, s.id, { seed: id, far: s.far, exp: s.exp, silent: s.silent, deps: s.deps })) {
          return false;
        }
        continue;
      }
      // Evaluate the step, with its own frame and expectations.
      this.pushFrame(g.start, g.gp);
      g.exp = this.isolate();
      return true;
    }
  }

  // growStep receives the result v of a step and adopts it as the seed if the match grew.
  growStep(g: GrowState, v: R): void {
    const ok = v !== undefined;
    if (!g.ctx) {
      const rec = this.gamma[g.gi]!;
      const best = rec.seed;
      if (!ok || (best.ok && this.pos <= best.end)) {
        g.done = true;
        return;
      }
      this.spend();
      rec.seed = newCtxResult(v, this.pos, false, this.recSince(g.rec), 0, noExp);
      rec.id = this.nextSeedID();
      this.pos = g.start;
      this.recovered.length = g.rec;
      return;
    }
    const id = this.gamma[g.gi]!.id;
    const ds = this.popFrame().deps;
    const far = this.unisolate(g.exp);
    const exp = this.isoIds;
    this.mergeKept(far, exp);
    let res = newCtxResult(v, ok ? this.pos : g.start, this.silent > 0, ok ? this.recSince(g.rec) : noErrs, 0, noExp);
    const c = this.canonicalSeed(g, res);
    res = c.e;
    const sd = this.stored(ds);
    const slot = newSlot(res, c.id, null);
    slot.far = far;
    slot.exp = exp;
    slot.silent = this.silent > 0;
    this.ctxStore(g.start, g.gp, headKey(ctxStepKind, g.rule, g.min, g.present), sd, slot);
    this.mergeDeps(ds);
    this.advance(g, res, c.id, { seed: id, far, exp, silent: this.silent > 0, deps: sd });
  }

  // nextSeedID returns a new seed identity.
  nextSeedID(): number {
    this.seedSeq++;
    return this.seedSeq + failSeed;
  }

  // advance continues the growth in a context after a step from the current seed with result res: it
  // extends or ends the run of steps that read no other seed, and adopts res if the match grew. It
  // reports whether the growth continues.
  advance(g: GrowState, res: CtxResult, rid: number, st: RunStep): boolean {
    const best = this.gamma[g.gi]!.seed;
    const grew = res.ok && (!best.ok || res.end > best.end);
    let other = false;
    const obs: Sdep[] = [];
    for (const d of st.deps) {
      if (d.kind === depSeed && (d.rule !== g.rule || d.min !== g.min)) {
        other = true;
      } else if (d.kind === depShadow && d.rule === g.rule && d.min === g.min) {
        // A lookahead of the step read the growth's own seed: its outcome holds for this seed
        // only, while a jump checks its observations under the first seed of the run.
        other = true;
      } else if (d.kind === depObs || d.kind === depShadow) {
        obs.push(d);
      }
    }
    if (grew && !other && res.errs.length === 0) {
      st.deps = obs;
      g.run.push(st);
    } else {
      this.recordJumps(g);
    }
    if (!grew) {
      g.done = true;
      return false;
    }
    this.spend();
    this.setSeed(g, res, rid);
    this.pos = g.start;
    this.recovered.length = g.rec;
    return true;
  }

  // setSeed makes e, with identity id, the seed of the growth in a context.
  setSeed(g: GrowState, e: CtxResult, id: number): void {
    const rec = this.gamma[g.gi]!;
    rec.seed = e;
    rec.id = id;
  }

  // growEnd ends the growth and returns its last result, which the call stores.
  growEnd(g: GrowState): CtxResult {
    this.recordJumps(g);
    this.dropTable(g.gi);
    const best = this.gamma[g.gi]!.seed;
    this.gamma.length = g.gi;
    this.pos = best.end;
    this.recovered.length = g.rec;
    for (const x of best.errs) {
      this.spend();
      this.recovered.push(x);
    }
    return best;
  }

  // recordJumps records, for each seed of the run, a jump to the current seed with what the steps
  // from that seed on recorded, and starts a new run.
  recordJumps(g: GrowState): void {
    if (g.run.length === 0) {
      return;
    }
    const t = this.table(g.start, g.gp, true)!;
    if (t.jumps === null) {
      t.jumps = new Map();
    }
    const cur = this.gamma[g.gi]!;
    let acc: JumpRec = { end: cur.seed, id: cur.id, far: -1, exp: noExp, silent: false, deps: noSdeps };
    for (let i = g.run.length - 1; i >= 0; i--) {
      const s = g.run[i]!;
      this.spend();
      acc = { ...acc };
      if (s.far > acc.far) {
        acc.far = s.far;
        acc.exp = s.exp;
      } else if (s.far === acc.far) {
        acc.exp = this.unionExpected(acc.exp, s.exp);
      }
      acc.silent = acc.silent || s.silent;
      acc.deps = mergeSdeps(acc.deps, s.deps);
      const k = jumpKey(g, s.seed);
      const js = t.jumps.get(k);
      if (js === undefined) {
        t.jumps.set(k, [acc]);
      } else if (!this.jumpShadowed(js, acc)) {
        js.push(acc);
      }
    }
    g.run.length = 0;
  }

  // jumpShadowed reports whether findJump never returns the jump j after the jumps js: one of them
  // is used wherever j is, since its observations are among j's and it is not inside a lookahead
  // where j is not. Leaving such jumps out keeps the list of a seed from growing in each growth that
  // ends its run there again, with the same observations and other shadows.
  jumpShadowed(js: JumpRec[], j: JumpRec): boolean {
    next: for (const e of js) {
      this.spend();
      if (e.silent && !j.silent) {
        continue;
      }
      for (const d of e.deps) {
        if (d.kind === depObs && !j.deps.some((x) => x.kind === depObs && x.site === d.site && x.val === d.val)) {
          continue next;
        }
      }
      return true;
    }
    return false;
  }

  // findJump returns a jump from the seed with identity id that holds in the current context.
  findJump(g: GrowState, id: number): JumpRec | null {
    const t = this.table(g.start, g.gp, false);
    if (t === null || t.jumps === null) {
      return null;
    }
    this.spend();
    const js = t.jumps.get(jumpKey(g, id));
    if (js === undefined) {
      return null;
    }
    next: for (const j of js) {
      this.spend();
      if (j.silent && this.silent === 0) {
        continue;
      }
      // Each step of the jump made its observations under its own seed, and the jump is taken from
      // the first: an observation holds for the jump only if its outcome is the same for every seed
      // of the growth.
      for (const d of j.deps) {
        if (d.kind !== depObs) {
          continue;
        }
        const o = this.obsFree(g.start, g.gp, g.present, d.site, g);
        if (o.v !== d.val || !o.free) {
          continue next;
        }
      }
      return j;
    }
    return null;
  }

  // unionExpected returns the expectations of a and b, at the same farthest position.
  unionExpected(a: number[], b: number[]): number[] {
    if (b.length === 0) {
      return a;
    }
    const out = a.slice();
    for (const x of b) {
      this.spend();
      if (!out.includes(x)) {
        out.push(x);
      }
    }
    return out;
  }

  // canonicalSeed returns the identity of the result e of a growth step, the same as an earlier
  // equal result's of the leader at the position, whose result it then returns instead of e.
  canonicalSeed(g: GrowState, e: CtxResult): { e: CtxResult; id: number } {
    const id = this.nextSeedID();
    if (!e.ok || e.errs.length > 0) {
      return { e, id };
    }
    const t = this.table(g.start, g.gp, true)!;
    if (t.canon === null) {
      t.canon = new Map();
    }
    const ck = g.rule + "," + g.min + "," + e.end;
    this.spend();
    const c = t.canon.get(ck);
    if (c !== undefined) {
      const budget = { n: 64 };
      if (c.e.errs.length === 0 && this.nodesEqual(c.e.node ?? null, e.node ?? null, budget)) {
        return c;
      }
    }
    const rec = { e, id };
    t.canon.set(ck, rec);
    return rec;
  }

  // nodesEqual reports whether two trees are equal, comparing at most budget.n pairs of distinct
  // nodes (false beyond: two results that are not shown equal get different identities, which costs
  // only reuse).
  nodesEqual(a: Node | null, b: Node | null, budget: { n: number }): boolean {
    if (a === b) {
      return true;
    }
    if (a === null || b === null) {
      return false;
    }
    if (--budget.n < 0) {
      return false;
    }
    this.spend();
    if (Object.getPrototypeOf(a) !== Object.getPrototypeOf(b) || a.type !== b.type || a.rule !== b.rule || a.start !== b.start || a.end !== b.end ||
      a.text !== b.text || a.fresh !== b.fresh || a.terminal !== b.terminal || a.labeled !== b.labeled || a.box !== null || b.box !== null ||
      (a instanceof TypedNode && a.base !== (b as TypedNode).base) ||
      a.children.length !== b.children.length || a.fields.length !== b.fields.length) {
      return false;
    }
    for (let i = 0; i < a.children.length; i++) {
      if (!this.nodesEqual(a.children[i] ?? null, b.children[i] ?? null, budget)) {
        return false;
      }
    }
    for (let i = 0; i < a.fields.length; i++) {
      const fa = a.fields[i]!, fb = b.fields[i]!;
      if (fa.name !== fb.name) {
        return false;
      }
      const va = fa.value, vb = fb.value;
      if (va instanceof Node || vb instanceof Node) {
        if (!(va instanceof Node && vb instanceof Node) || !this.nodesEqual(va, vb, budget)) {
          return false;
        }
      } else if (va !== vb) {
        return false;
      }
    }
    return true;
  }

  // invoke evaluates the body of r and makes the rule's value.
  invoke(r: Rule, min: number): R {
    const f = this.newFrame(r.scope.length);
    const prevFrame = this.frame;
    const prevEnv = this.env;
    const prevCut = this.cut;
    const trail = this.trail.length;
    this.frame = f;
    this.cut = false;
    if (r.rec && ++this.depth > this.maxDepth) {
      this.tooDeep();
    }
    const start = this.pos;
    this.observation?.evaluated();
    let v = r.body(this, min);
    if (r.rec) this.depth--;
    this.frame = prevFrame;
    this.cut = prevCut;
    this.trail.length = trail;
    if (v !== undefined) {
      v = this.finish(r, f, v, start);
    }
    this.env = prevEnv;
    return v;
  }

  // invokePlain is an unmemoized call of a rule without captures: invoke without the capture
  // frame (the body never writes one, so the caller's stays current), with the failure handling of
  // call.
  invokePlain(r: Rule, min: number): R {
    const o = this.observation;
    if (o === null) {
      this.spend();
      return this.invokePlainBody(r, min);
    }
    o.enter(r.name, this.pos, min);
    this.spend();
    const v = this.invokePlainBody(r, min);
    o.exit(v !== undefined, this.pos);
    return v;
  }

  // invokePlainBody is invokePlain without the step of the entry, which the caller charges.
  invokePlainBody(r: Rule, min: number): R {
    const start = this.pos;
    const rec = this.recovered.length;
    const trail = this.trail.length;
    const prevEnv = this.env;
    const prevCut = this.cut;
    this.cut = false;
    if (r.rec && ++this.depth > this.maxDepth) {
      this.tooDeep();
    }
    this.observation?.evaluated();
    let v = r.body(this, min);
    if (r.rec) this.depth--;
    this.cut = prevCut;
    this.trail.length = trail;
    if (v !== undefined) {
      v = this.finish(r, emptyFrame, v, start);
    } else {
      this.pos = start;
      this.recovered.length = rec;
    }
    this.env = prevEnv;
    return v;
  }

  // tooDeep fails the parse for exceeding the nesting limit.
  tooDeep(): never {
    throw new Fatal(new Error(`nesting too deep: more than ${this.maxDepth} nested recursive rule calls`));
  }

  // finish makes the rule's value from the value of its body.
  finish(r: Rule, f: Frame, v: Node | null, start: number): Node | null {
    v = this.finishValue(r, f, v, start);
    if (r.nodeType !== "") {
      v = this.convertResult(r, v);
    }
    return v;
  }

  // convertResult converts v, the value of rule r, to the rule's named node type.
  convertResult(r: Rule, v: Node | null): Node {
    const u = unboxNode(v);
    const n = convertNode(r.nodeType, u);
    if (n === null) {
      throw new Fatal(new Error(`cannot convert ${typeName(u)} to ${r.nodeType} in result of rule ${r.where || r.name}`));
    }
    return n;
  }

  finishValue(r: Rule, f: Frame, v: Node | null, start: number): Node | null {
    if (r.novalue) {
      return null;
    }
    if (r.action !== null) {
      const c = this.useCtx(f, start, this.pos, null, null, null);
      if (r.operatorsRule !== null) {
        c.value = v; // the folded value, $value of the whole-rule action
      }
      return c.result(r.action, r.where || r.name);
    }
    if (r.splice) {
      if (v !== null) {
        v.fresh = false;
      }
      return v;
    }
    v = this.scopeValue(r.value, v, start);
    if (r.scope.length > 0) {
      v = this.attachCaptures(v, r.scope, f, start, this.pos);
    }
    if (v === null) {
      return null;
    }
    if (v.fresh) {
      if (this.sourceInfo && v.rule === "") {
        v.rule = r.name;
      }
      v.fresh = false;
    }
    return v;
  }

  // attachCaptures attaches the non-null captures as fields of the node. A node of another rule, or
  // one that is itself captured, is first wrapped in a tuple node.
  attachCaptures(v: Node | null, names: string[], f: Frame, start: number, end: number): Node | null {
    let found = false;
    let wrap = v === null || !v.fresh;
    for (const c of f) {
      this.spend();
      if (c !== null) {
        found = true;
        if (c === v) {
          wrap = true;
        }
      }
    }
    if (!found) {
      return v;
    }
    let n = v as Node;
    if (wrap) {
      n = new Node("tuple", "", start, end, "", [v], noFields, true, false);
    }
    n.labeled = this.sourceInfo;
    for (let i = 0; i < names.length; i++) {
      this.spend();
      const c = f[i]!;
      if (c !== null) {
        setField(n, names[i]!, c, this.control);
      }
    }
    return n;
  }

  // --- Shapes of values ---
  //
  // A shaper (Shaper) converts the result of an expression's matcher to the value where the
  // expression takes one element (an alternative, the operand of ?, a capture or a recovered
  // expression) or is a scope (a rule body, a repetition element or an Operators Rule line).

  // shapeTuple returns the tuple node of the result v of a match of [start, this.pos).
  shapeTuple(s: Shaper, v: Node | null, start: number): Node {
    if ((s & shaperElems) !== 0) {
      if ((s & shaperShared) !== 0 && v !== null) {
        return new Node("tuple", "", v.start, v.end, "", v.children, noFields, true, false);
      }
      return v as Node;
    }
    return new Node("tuple", "", start, this.pos, "", s >> 5 === 1 ? [v] : [], noFields, true, false);
  }

  // shapeSingle returns the value of the result v where the expression takes one element, or null
  // when it has no value.
  shapeSingle(s: Shaper, v: Node | null, start: number): Node | null {
    switch ((s >> 2) & 3) {
      case singlePass:
        return shaperOne(s, v);
      case singleTuple:
        return this.shapeTuple(s, v, start);
    }
    return null;
  }

  // shapeCapture is shapeSingle for a capture or a recovered expression, whose value is the unit
  // node of the range matched when the expression has no value.
  shapeCapture(s: Shaper, v: Node | null, start: number): Node | null {
    if (((s >> 2) & 3) === singleNone) {
      return new Node("tuple", "", start, this.pos, "", [], noFields, true, false);
    }
    return this.shapeSingle(s, v, start);
  }

  // scopeValue returns the value of a scope whose body matched [start, this.pos) with the result v.
  scopeValue(s: Shaper, v: Node | null, start: number): Node | null {
    if ((s & shaperTuple) !== 0) {
      return this.shapeTuple(s, v, start);
    }
    return shaperOne(s, v);
  }

  // nodeValue returns the Value of the node n: its text for a string node, and a tuple or list
  // value sharing its elements otherwise.
  nodeValue(n: Node): Value {
    if (n.terminal) {
      return n.text;
    }
    return new Node(nodeShape(n) === shapeList ? typeListValue : typeTupleValue, "", n.start, n.end, "", n.children, noFields, false, false);
  }

  // --- Terminals ---

  matchLiteral(lit: Lit, desc: number, build: boolean): R {
    this.spend();
    const start = this.pos;
    if (this.unit === Bytes) {
      const b = lit.bytes;
      if (this.pos + b.length > this.n) {
        return this.matchReplacementLiteral(lit, desc, build);
      }
      for (let i = 0; i < b.length; i++) {
        this.control?.charge(1);
        if (this.bs[this.pos + i] !== b[i]) {
          return this.matchReplacementLiteral(lit, desc, build);
        }
      }
      this.pos += b.length;
    } else {
      for (const r of lit.cps) {
        this.control?.charge(1);
        if (this.pos >= this.n || this.cps[this.pos] !== r) {
          this.expect(start, desc);
          return undefined;
        }
        this.pos++;
      }
    }
    if (!build) {
      return null;
    }
    return new Node("string", "", start, this.pos, lit.text, noNodes, noFields, true, true);
  }

  // matchLiteralFold matches a case-insensitive literal. lit.cps holds the literal with each ASCII
  // letter lowercased; each input character is folded the same way before it is compared.
  matchLiteralFold(lit: Lit, desc: number, build: boolean): R {
    this.spend();
    const start = this.pos;
    for (const want of lit.cps) {
      const got = this.peek();
      if (got < 0 || foldASCII(got) !== want) {
        this.expect(start, desc);
        return undefined;
      }
      this.pos += this.psize;
    }
    if (!build) {
      return null;
    }
    return new Node("string", "", start, this.pos, this.text(start, this.pos), noNodes, noFields, true, true);
  }

  // Keep replacement decoding off the successful byte-comparison path.
  matchReplacementLiteral(lit: Lit, desc: number, build: boolean): R {
    const start = this.pos;
    let replacement = false;
    if (this.control === null) {
      replacement = lit.cps.includes(0xfffd);
    } else {
      for (const cp of lit.cps) {
        this.spend();
        if (cp === 0xfffd) { replacement = true; break; }
      }
    }
    if (!replacement) {
      this.expect(start, desc);
      return undefined;
    }
    for (const want of lit.cps) {
      if (this.peek() !== want) {
        this.expect(start, desc);
        return undefined;
      }
      this.pos += this.psize;
    }
    if (!build) {
      return null;
    }
    return new Node("string", "", start, this.pos, this.text(start, this.pos), noNodes, noFields, true, true);
  }

  atLineStart(): boolean {
    if (this.pos === 0) {
      return true;
    }
    this.control?.charge(1);
    return (this.unit === Bytes ? this.bs[this.pos - 1] : this.cps[this.pos - 1]) === 0x0a;
  }

  atLineEnd(): boolean {
    const ch = this.peek();
    return ch < 0 || ch === 0x0a || ch === 0x0d;
  }

  atEnd(): boolean {
    this.control?.charge(1);
    return this.pos === this.n;
  }

  // --- Actions and predicates ---

  // useCtx sets up the parser's single evaluation context and returns it. Evaluations never nest,
  // and no reference to the context survives one, so one context per parser can be reused.
  useCtx(f: Frame, start: number, end: number, lhs: Value, rhs: Value, op: Value): Actx {
    const c = this.ac;
    c.f = f;
    c.start = start;
    c.end = end;
    c.cbase = this.created.length;
    c.lhs = lhs;
    c.rhs = rhs;
    c.op = op;
    c.value = null;
    return c;
  }

  predicate(t: Action): boolean {
    const base = this.created.length;
    const kids = this.kidStack.length;
    try {
      const v = t(this.useCtx(this.frame, this.pos, this.pos, null, null, null));
      return v !== false;
    } catch (x) {
      if (!(x instanceof EvalError)) {
        throw x;
      }
      this.dropKids(kids); // elements gathered by a list built-in that failed
      return false;
    } finally {
      this.created.length = base; // drop nodes created by the predicate
    }
  }

  // bind binds the value of t to the variable in slot. The compiler has checked that the value
  // fits the variable.
  bind(slot: number, t: Action): boolean {
    const base = this.created.length;
    const kids = this.kidStack.length;
    try {
      const v = t(this.useCtx(this.frame, this.pos, this.pos, null, null, null));
      if (typeof v === "function") {
        return false;
      }
      this.bindValue(slot, v);
      return true;
    } catch (x) {
      if (!(x instanceof EvalError)) {
        throw x;
      }
      this.dropKids(kids); // elements gathered by a list built-in that failed
      return false;
    } finally {
      this.created.length = base; // drop nodes created by the predicate
    }
  }

  // bindValue rebinds the variable in slot i, copying the path to the slot and preserving
  // environments saved for rollback. Binding the value it has already is a no-op. Under budget
  // controls it costs one unit for the old value and one for each array that a rebind copies.
  bindValue(slot: number, val: Value): void {
    const control = this.control;
    this.spend();
    const old = envGet(this.env!, slot, this.envDepth);
    // Variables are checked scalar values; an equal binding has no effect.
    if (control === null ? old === val : equalValuesSpend(old, val, control)) return;
    this.spend(this.envDepth + 1);
    this.env = envSet(this.env!, slot, this.envDepth, val);
  }

  // --- OperatorsRule expressions ---

  skipTrivia(pr: OperatorsRule): void {
    if (pr.skip === null) {
      return;
    }
    const m0pos = this.pos;
    const m0env = this.env;
    const m0trail = this.trail.length;
    const m0rec = this.recovered.length;
    this.silent++;
    const v = pr.skip(this);
    this.silent--;
    if (v === undefined) {
      this.reset(m0pos, m0env, m0trail, m0rec);
    }
  }

  // longest tries every operator and returns the longest match (the first declared among equals),
  // or null when none matched. cutFailed is set when a candidate failed after a cut.
  longest(ops: OperatorsRuleOp[]): OperatorsRuleAttempt | null {
    const m0pos = this.pos;
    const m0env = this.env;
    const m0trail = this.trail.length;
    const m0rec = this.recovered.length;
    let best: OperatorsRuleAttempt | null = null;
    let cutFailed = false;
    for (const op of ops) {
      this.spend();
      const prevFrame = this.frame;
      const prevCut = this.cut;
      const f = this.newFrame(op.line.scope.length);
      this.frame = f;
      this.cut = false;
      const v = op.line.m(this);
      let ok = v !== undefined;
      const cut = this.cut;
      this.frame = prevFrame;
      this.cut = prevCut;
      if (ok && this.pos === m0pos && op.kind !== "infix") {
        ok = false; // an empty prefix or postfix match could be applied forever
      }
      if (ok && (best === null || this.pos > best.end)) {
        best = {
          op,
          frame: f,
          v: v as Node | null,
          start: m0pos,
          end: this.pos,
          env: this.env,
          cut,
          errs: this.recovered.length > m0rec ? (this.control === null ? this.recovered.slice(m0rec) : copyErrorsSpend(this.recovered, m0rec, this.recovered.length, this.control)) : noErrs,
        };
      }
      if (!ok && cut) {
        cutFailed = true;
      }
      if (f.length === 0) {
        this.reset(m0pos, m0env, m0trail, m0rec);
        continue;
      }
      // reset undoes this candidate's captures; restore them. Nothing parses between saving
      // and restoring, so one buffer per parser suffices.
      this.saved.length = 0;
      for (const x of f) {
        this.spend();
        this.saved.push(x);
      }
      this.reset(m0pos, m0env, m0trail, m0rec);
      for (let i = 0; i < f.length; i++) {
        this.spend();
        f[i] = this.saved[i]!;
      }
    }
    this.cutFailed = cutFailed;
    return best;
  }

  // cutFailed reports that a candidate of the last longest failed after a cut.
  cutFailed = false;

  apply(a: OperatorsRuleAttempt): void {
    this.pos = a.end;
    this.env = a.env;
    for (const x of a.errs) {
      this.spend();
      this.recovered.push(x);
    }
  }

  // operatorsRuleParse parses an expression with operators that bind tighter than min. Each level of its
  // recursion (the operand of a prefix operator, the right operand of an infix operator) counts
  // against the nesting limit, like the entry of a recursive rule. The call of the rule charges its entry; the loops
  // of the expression charge each iteration.
  operatorsRuleParse(r: Rule, min: number): R {
    if (++this.depth > this.maxDepth) {
      this.tooDeep();
    }
    const v = this.operatorsRuleExpr(r, min);
    this.depth--;
    return v;
  }

  operatorsRuleExpr(r: Rule, min: number): R {
    const pr = r.operatorsRule as OperatorsRule;
    let lhs = this.operatorsRuleNud(r);
    if (lhs === undefined) {
      return undefined;
    }
    let lastNone = -1;
    for (;;) {
      this.spend();
      const m0pos = this.pos;
      const m0env = this.env;
      const m0trail = this.trail.length;
      const m0rec = this.recovered.length;
      this.skipTrivia(pr);
      const a = this.longest(pr.led);
      if (a === null) {
        const cutFailed = this.cutFailed;
        this.reset(m0pos, m0env, m0trail, m0rec);
        if (cutFailed) {
          return undefined;
        }
        break;
      }
      if (a.op.level <= min || (a.op.assoc === "none" && a.op.level === lastNone)) {
        this.reset(m0pos, m0env, m0trail, m0rec);
        break;
      }
      this.apply(a);
      if (a.op.kind === "postfix") {
        lhs = this.operatorsRuleBuild(r, a, lhs, null);
        lastNone = -1;
        if (this.pos === m0pos) {
          break;
        }
        continue;
      }
      let rmin = a.op.level;
      if (a.op.assoc === "right") {
        rmin--;
      }
      const rhs = this.operatorsRuleParse(r, rmin);
      if (rhs === undefined) {
        if (a.cut) {
          return undefined;
        }
        this.reset(m0pos, m0env, m0trail, m0rec);
        break;
      }
      lhs = this.operatorsRuleBuild(r, a, lhs, rhs);
      lastNone = -1;
      if (a.op.assoc === "none") {
        lastNone = a.op.level;
      }
      // An application that consumed no input ends the loop, as an empty iteration ends a
      // repetition: otherwise an operator that can match empty after an operand that can loops
      // forever.
      if (this.pos === m0pos) {
        break;
      }
    }
    return lhs;
  }

  operatorsRuleNud(r: Rule): R {
    const pr = r.operatorsRule as OperatorsRule;
    this.skipTrivia(pr);
    const m0pos = this.pos;
    const m0env = this.env;
    const m0trail = this.trail.length;
    const m0rec = this.recovered.length;
    const a = this.longest(pr.prefix);
    if (a !== null) {
      this.apply(a);
      const rhs = this.operatorsRuleParse(r, a.op.level);
      if (rhs !== undefined) {
        return this.operatorsRuleBuild(r, a, null, rhs);
      }
      if (a.cut) {
        return undefined;
      }
      this.reset(m0pos, m0env, m0trail, m0rec);
    } else if (this.cutFailed) {
      return undefined;
    }
    for (const o of pr.operands) {
      this.spend();
      const prevFrame = this.frame;
      const prevCut = this.cut;
      const f = this.newFrame(o.scope.length);
      this.frame = f;
      this.cut = false;
      const v = o.m(this);
      const cut = this.cut;
      this.frame = prevFrame;
      this.cut = prevCut;
      if (v !== undefined) {
        return this.lineResult(r, o, f, v, m0pos);
      }
      this.reset(m0pos, m0env, m0trail, m0rec);
      if (cut) {
        return undefined;
      }
    }
    return undefined;
  }

  lineResult(r: Rule, l: OperatorsRuleLine, f: Frame, v: Node | null, start: number): Node | null {
    if (r.novalue) {
      return null;
    }
    return this.lineValue(r, l, f, v, start);
  }

  lineValue(r: Rule, l: OperatorsRuleLine, f: Frame, v: Node | null, start: number): Node | null {
    if (l.action !== null) {
      const c = this.useCtx(f, start, this.pos, null, null, null);
      return c.result(l.action, r.where || r.name);
    }
    v = this.scopeValue(l.value, v, start);
    if (l.scope.length > 0) {
      v = this.attachCaptures(v, l.scope, f, start, this.pos);
    }
    if (v !== null && v.fresh) {
      if (this.sourceInfo && v.rule === "") {
        v.rule = r.name;
      }
      v.fresh = false;
    }
    return v;
  }

  operatorsRuleBuild(r: Rule, a: OperatorsRuleAttempt, lhs: Node | null, rhs: Node | null): Node | null {
    if (r.novalue) {
      return null;
    }
    let start = a.start;
    let end = this.pos;
    if (lhs !== null) {
      start = lhs.start;
    }
    if (a.op.kind === "postfix") {
      end = a.end;
    }
    const l = a.op.line;
    // The operator's value is its one element, or the node of its tuple, which has the line's
    // captures.
    let opv: Node | null;
    if (((l.value >> 2) & 3) === singleNone) {
      opv = new Node("tuple", "", a.start, a.end, "", [], noFields, false, false);
    } else {
      opv = this.shapeSingle(l.value, a.v, a.start);
    }
    if (((l.value >> 2) & 3) === singleTuple && l.scope.length > 0) {
      opv = this.attachCaptures(opv, l.scope, a.frame, a.start, a.end);
    }
    if (opv !== null) {
      opv.fresh = false;
    }
    if (l.action !== null) {
      const c = this.useCtx(a.frame, start, end, unboxNode(lhs), unboxNode(rhs), unboxNode(opv));
      let v = c.result(l.action, r.where || r.name);
      if (r.opNodeType !== "") {
        v = this.convertOperator(r, v);
      }
      return v;
    }
    // Without an action, the application is the node of the tuple (lhs, op, rhs) of the line's
    // kind, with those captures.
    let kids: (Node | null)[];
    let fields: NodeField[];
    switch (a.op.kind) {
      case "prefix":
        kids = [opv, rhs];
        fields = [{ name: "op", value: opv }, { name: "rhs", value: rhs }];
        break;
      case "postfix":
        kids = [lhs, opv];
        fields = [{ name: "lhs", value: lhs }, { name: "op", value: opv }];
        break;
      default:
        kids = [lhs, opv, rhs];
        fields = [{ name: "lhs", value: lhs }, { name: "op", value: opv }, { name: "rhs", value: rhs }];
    }
    if (r.opNodeType !== "") {
      // The node of the operators' named node type, built without the tuple node it converts from.
      const t = new TypedNode(r.opNodeType, start, end, "", kids, fields, false, shapeTuple);
      t.labeled = this.sourceInfo;
      return t;
    }
    const n = new Node("tuple", this.sourceInfo ? r.name : "", start, end, "", kids, fields, false, false);
    n.labeled = this.sourceInfo;
    return n;
  }

  // convertOperator converts v, the value of an operator of rule r, to the named node type of the
  // rule's operators.
  convertOperator(r: Rule, v: Node | null): Node {
    const u = unboxNode(v);
    const n = convertNode(r.opNodeType, u);
    if (n === null) {
      throw new Fatal(new Error(`cannot convert ${typeName(u)} to ${r.opNodeType} in result of rule ${r.where || r.name}`));
    }
    return n;
  }
}

// codePointsString returns the string of the code points cps.
export function codePointsString(cps: Int32Array): string {
  const parts: string[] = [];
  const chunk = 4096;
  for (let i = 0; i < cps.length; i += chunk) {
    parts.push(String.fromCodePoint(...cps.subarray(i, Math.min(i + chunk, cps.length))));
  }
  return parts.join("");
}

// Fatal is an error that ends the parse (a runtime error in an action, or too deep nesting).
export class Fatal {
  err: Error;
  constructor(err: Error) {
    this.err = err;
  }
}

// EvalError is an error in evaluating a value expression. It fails the whole parse in an action
// and makes a predicate fail.
export class EvalError {
  msg: string;
  constructor(msg: string) {
    this.msg = msg;
  }
}

export function evalError(msg: string): never {
  throw new EvalError(msg);
}

// Actx is the context of evaluating an action or a predicate.
export class Actx {
  p: Parser;
  f: Frame = emptyFrame;
  start = 0;
  end = 0;
  cbase = 0; // start of p.created made by this evaluation
  lhs: Value = null;
  rhs: Value = null;
  op: Value = null;
  value: Value = null; // the folded value of an Operators Rule, in its whole-rule action

  constructor(p: Parser) {
    this.p = p;
  }

  spend(): void { this.p.spend(); }

  binary(op: string, l: Value, r: Value): Value {
    const control = this.p.control;
    if (control !== null && typeof l === "string" && typeof r === "string") {
      switch (op) {
        case "==": case "!=": {
          const equal = equalStringsSpend(l, r, control);
          return op === "==" ? equal : !equal;
        }
        case "+": return joinValueStringsSpend([l, r], control);
        case "<": return compareStringsSpend(l, r, control) < 0;
        case "<=": return compareStringsSpend(l, r, control) <= 0;
        case ">": return compareStringsSpend(l, r, control) > 0;
        case ">=": return compareStringsSpend(l, r, control) >= 0;
      }
    }
    return rtBinary(op, l, r);
  }

  result(action: Action, where: string): Node | null {
    try {
      const v = action(this);
      if (v === null) {
        return null;
      }
      if (!(v instanceof Node)) {
        if (typeof (v as unknown) === "function") {
          return evalError("result must be a value, got a function");
        }
        // A value other than a node travels boxed, with the range of the action's input.
        const b = new Node(typeBox, "", this.start, this.end, "", noNodes, noFields, false, false);
        b.box = v;
        return b;
      }
      const n = v;
      const created = this.p.created;
      for (let i = this.cbase; i < created.length; i++) {
        this.spend();
        if (created[i] === n) {
          n.start = this.start;
          n.end = this.end;
          break;
        }
      }
      n.fresh = false; // the value of an action is final (see the engine's actionResult)
      return n;
    } catch (x) {
      if (x instanceof EvalError) {
        throw new Fatal(new Error(`action in ${where}: ${x.msg}`));
      }
      throw x;
    } finally {
      this.p.created.length = this.cbase;
    }
  }

  cap(slot: number): Value {
    return unboxValue(this.f[slot]!);
  }

  // variable returns the value of the variable in slot i.
  variable(slot: number): Value {
    return this.p.variable(slot);
  }

  // convert evaluates a node type constructor T{v}: it converts v to the named node type typ.
  convert(typ: string, v: Value): Value {
    const u = unboxValue(v);
    const n = convertNode(typ, u);
    return n === null ? evalError(`cannot convert ${typeName(u)} to ${typ}`) : n;
  }

  newStruct(typ: string, ...kv: Value[]): Value {
    const n = new Node(typ, "", 0, 0, "", noNodes, noFields, false, false);
    let first = true;
    for (let i = 0; i < kv.length; i += 2) {
      this.spend();
      const v = kv[i + 1];
      setField(n, kv[i] as string, v!, this.p.control);
      if (v instanceof Node) {
        if (first || v.start < n.start) {
          n.start = v.start;
        }
        if (first || v.end > n.end) {
          n.end = v.end;
        }
        first = false;
      }
    }
    if (first) {
      n.start = this.start;
      n.end = this.end;
    }
    this.p.created.push(n);
    return n;
  }

  newList(items: readonly (Node | null)[]): Node {
    return this.listNode(this.p.control === null ? items.slice() : copyNodesSpend(items, 0, items.length, this.p.control));
  }

  // listNode returns a list value with the child list kids (which it takes over). Its range, which
  // the value model does not show, covers the elements that are nodes.
  listNode(kids: (Node | null)[]): Node {
    return this.valueNode(typeListValue, kids);
  }

  // tuple returns a tuple value of the arguments, as a tuple literal builds it.
  tuple(...args: Value[]): Value {
    const base = this.p.kidStack.length;
    this.spend();
    for (const a of args) {
      this.spend();
      const v = this.element("tuple", a);
      this.p.kidStack.push(v);
    }
    return this.valueNode(typeTupleValue, this.p.kids(base));
  }

  valueNode(type: string, kids: (Node | null)[]): Node {
    const n = new Node(type, "", this.start, this.start, "", kids, noFields, false, false);
    let first = true;
    for (const it of kids) {
      this.spend();
      if (it === null) {
        continue;
      }
      if (first || it.start < n.start) {
        n.start = it.start;
      }
      if (first || it.end > n.end) {
        n.end = it.end;
      }
      first = false;
    }
    return n;
  }

  member(x: Value, name: string): Value {
    if (!(x instanceof Node)) {
      return evalError(`cannot access .${name} of ${typeName(x)}`);
    }
    if (isValueNode(x)) {
      switch (name) {
        case "Start":
          return x.start;
        case "End":
          return x.end;
        case "Value":
          return this.p.nodeValue(x);
      }
    }
    const fields = this.p.g.structFields.get(x.type);
    if (name.startsWith("$")) {
      // x.$y reads a capture, which struct values do not have; an unmatched capture is null.
      if (fields !== undefined) {
        evalError(`${x.type} has no capture ${name.slice(1)}`);
      }
      return unboxValue(getFieldSpend(x, name.slice(1), this.p.control));
    }
    if (fields !== undefined && !fields.has(name)) {
      evalError(`${x.type} has no field ${name}`);
    }
    return getFieldSpend(x, name, this.p.control);
  }

  length(x: Value): Value {
    if (typeof x === "string") {
      return this.p.unitLen(x);
    }
    if (x === null) {
      return 0;
    }
    if (x instanceof Node) {
      if (x.terminal) {
        // The text of a string node is the input of its range, whose length the range holds in
        // the position unit.
        return x.end - x.start;
      }
      return x.children.length;
    }
    return evalError(`len: invalid argument ${typeName(x)}`);
  }

  text(x: Value): Value {
    return this.textStr(x);
  }

  // textStr returns text(x) as a string.
  textStr(x: Value): string {
    if (x === null) {
      return "";
    }
    if (typeof x === "string") {
      return x;
    }
    if (x instanceof Node) {
      if (x.terminal) {
        return x.text;
      }
      return this.p.text(x.start, x.end);
    }
    return evalError(`text: invalid argument ${typeName(x)}`);
  }

  // The list built-ins gather the elements on kidStack (lambdas that build lists push above them)
  // and hand the copied-out slice to the list node. If one fails, the error unwinds to the action
  // (which fails the parse) or the predicate (which pops what was gathered).

  mapList(list: Value, f: (item: Value) => Value): Value {
    const base = this.p.kidStack.length;
    this.pushMap(list, f);
    return this.endList(base);
  }

  filterList(list: Value, f: (item: Value) => Value): Value {
    const base = this.p.kidStack.length;
    for (const item of listItems("filter", list)) {
      this.spend();
      const value = f(unboxValue(item));
      if (typeof value !== "boolean") {
        evalError(`filter: predicate must produce a bool, got ${typeName(value)}`);
      }
      if (value) {
        this.p.kidStack.push(item);
      }
    }
    return this.endList(base);
  }

  list(...args: Value[]): Value {
    const base = this.p.kidStack.length;
    this.pushList(...args);
    return this.endList(base);
  }

  concat(...args: Value[]): Value {
    const base = this.p.kidStack.length;
    for (const a of args) {
      this.spend();
      this.pushItems(a);
    }
    return this.endList(base);
  }

  // pushMap, pushList and pushItems push the elements that map, list and concat make from their
  // arguments. A concat call whose arguments are all list, map or such concat calls is generated
  // as pushes for its arguments followed by endList, so that they build no intermediate list.

  pushMap(list: Value, f: (item: Value) => Value): void {
    this.spend();
    for (const it of listItems("map", list)) {
      this.spend();
      const v = this.element("map", f(unboxValue(it)));
      this.p.kidStack.push(v);
    }
  }

  // element returns v as an element of a list that the list built-in fn makes. An int, string
  // or bool travels boxed, with the range of the action's input, as the result of an action does.
  element(fn: string, v: Value): Node | null {
    switch (typeof v) {
      case "number":
      case "bigint":
      case "string":
      case "boolean": {
        const b = new Node(typeBox, "", this.start, this.end, "", noNodes, noFields, false, false);
        b.box = v;
        return b;
      }
    }
    return asNode(fn, v);
  }

  pushList(...args: Value[]): void {
    this.spend();
    for (const a of args) {
      this.spend();
      const v = this.element("list", a);
      this.p.kidStack.push(v);
    }
  }

  pushItems(v: Value): void {
    this.spend();
    for (const it of listItems("concat", v)) {
      this.spend();
      this.p.kidStack.push(it);
    }
  }

  // endList returns a list of the elements pushed since base.
  endList(base: number): Value {
    return this.listNode(this.p.kids(base));
  }
}

export function typeName(v: unknown): string {
  if (v === null || v === undefined) {
    return "nil";
  }
  if (v instanceof Node) {
    if (v instanceof TypedNode) {
      return v.type;
    }
    return v.type === typeBox ? typeName(v.box) : valueTypeName(nodeShape(v), v.type, v.children.length);
  }
  switch (typeof v) {
    case "number":
    case "bigint":
      return "int";
    case "string":
      return "string";
    case "boolean":
      return "bool";
    case "function":
      return "func";
  }
  return typeof v;
}

// valueTypeName names the type of a value of the given shape in messages, in the terms of the value
// model: node[string] for a string node, node[(_, _)] and node[[]_] for tuple and list nodes (a
// tuple has elems elements), error for an error value, (_, _) and []_ for tuple and list values,
// and name for a struct.
export function valueTypeName(shape: number, name: string, elems: number): string {
  switch (shape) {
    case shapeString:
      return "node[string]";
    case shapeTuple:
      return `node[${tupleTerm(elems)}]`;
    case shapeList:
      return "node[[]_]";
    case shapeError:
      return "error";
    case shapeTupleValue:
      return tupleTerm(elems);
    case shapeListValue:
      return "[]_";
  }
  return name;
}

// tupleTerm is the type term of a tuple of n elements of unknown types.
export function tupleTerm(n: number): string {
  return n === 1 ? "(_,)" : `(${Array<string>(n).fill("_").join(", ")})`;
}

export function listItems(fn: string, v: Value): readonly (Node | null)[] {
  if (v === null) {
    return noNodes;
  }
  if (v instanceof Node) {
    return v.children;
  }
  return evalError(`${fn}: expected a list, got ${typeName(v)}`);
}

export function asNode(fn: string, v: Value): Node | null {
  if (v === null || v instanceof Node) {
    return v;
  }
  return evalError(`${fn}: elements must be values, got ${typeName(v)}`);
}

export function rtFold(fn: string, right: boolean, acc: Value, list: Value, f: (acc: Value, item: Value) => Value, control: BudgetControl | null = null): Value {
  const items = listItems(fn, list);
  for (let i = 0; i < items.length; i++) {
    control?.charge(1);
    acc = f(acc, unboxValue(items[right ? items.length - 1 - i : i]!));
  }
  return acc;
}

// --- Ints ---

// Ints are 64-bit and wrap around, as in Go. An int is a number while it is a safe integer and a
// bigint otherwise, so equal ints are always ===.

export const maxSafe = BigInt(Number.MAX_SAFE_INTEGER);

export function intOf(b: bigint): number | bigint {
  b = BigInt.asIntN(64, b);
  return b >= -maxSafe && b <= maxSafe ? Number(b) : b;
}

export function isInt(v: Value): v is number | bigint {
  return typeof v === "number" || typeof v === "bigint";
}

export function big(v: number | bigint): bigint {
  return typeof v === "bigint" ? v : BigInt(v);
}

export function rtUnary(op: string, x: Value): Value {
  switch (op) {
    case "-":
      if (typeof x === "number") {
        return 0 - x; // 0 - x, not -x, which is -0 for 0
      }
      if (typeof x === "bigint") {
        return intOf(-x);
      }
      break;
    case "!":
      if (typeof x === "boolean") {
        return !x;
      }
  }
  return evalError(`invalid operand ${typeName(x)} for unary ${op}`);
}

export function rtBool(op: string, v: Value): boolean {
  if (typeof v !== "boolean") {
    return evalError(`invalid operand ${typeName(v)} for ${op}`);
  }
  return v;
}

export function rtAnd(l: Value, r: () => Value): Value {
  if (!rtBool("&&", l)) {
    return false;
  }
  return rtBool("&&", r());
}

export function rtOr(l: Value, r: () => Value): Value {
  if (rtBool("||", l)) {
    return true;
  }
  return rtBool("||", r());
}

// comparisonHint is added to the error for comparing a node or another structured value, which
// == and != do not compare (see Operators in the language specification).
const comparisonHint = "nodes and other structured values cannot be compared; use text(x), or .Start and .End";

// scalarOrNil reports whether v is nil, an int, a string or a bool, the values that == and != compare.
function scalarOrNil(v: Value): boolean {
  if (v instanceof Node && v.type === typeBox) {
    return scalarOrNil(v.box as Value);
  }
  return v === null || v === undefined || typeof v === "number" || typeof v === "bigint" || typeof v === "string" || typeof v === "boolean";
}

// invalidOperands fails the action for applying op to l and r. A comparison of a node or another
// structured value says why it fails.
function invalidOperands(op: string, l: Value, r: Value): never {
  const hint = (op === "==" || op === "!=") && !(scalarOrNil(l) && scalarOrNil(r)) ? `: ${comparisonHint}` : "";
  return evalError(`invalid operands ${typeName(l)} and ${typeName(r)} for ${op}${hint}`);
}

// rtEqual applies == to l and r. It compares ints, strings and bools of one type, and any value with
// nil; it fails for every other pair, which has no equality.
function rtEqual(op: string, l: Value, r: Value): boolean {
  const a = l instanceof Node && l.type === typeBox ? (l.box as Value) : l;
  const b = r instanceof Node && r.type === typeBox ? (r.box as Value) : r;
  if (a === null || a === undefined || b === null || b === undefined) {
    return (a === null || a === undefined) && (b === null || b === undefined);
  }
  if (typeof a === typeof b && (typeof a === "string" || typeof a === "boolean")) {
    return a === b;
  }
  if (isInt(a) && isInt(b)) {
    return a === b;
  }
  return invalidOperands(op, l, r);
}

export function rtBinary(op: string, l: Value, r: Value): Value {
  switch (op) {
    case "==":
      return rtEqual(op, l, r);
    case "!=":
      return !rtEqual(op, l, r);
    case "[]": {
      const items = listItems("[]", l);
      if (!isInt(r)) {
        return evalError(`index must be int, got ${typeName(r)}`);
      }
      if (r < 0 || r >= items.length) {
        return evalError(`index ${r} out of range for ${items.length} elements`);
      }
      return unboxValue(items[Number(r)] ?? null);
    }
  }
  if (isInt(l) && isInt(r)) {
    const small = typeof l === "number" && typeof r === "number";
    switch (op) {
      case "+":
        if (small) {
          const s = (l as number) + (r as number);
          if (Number.isSafeInteger(s)) {
            return s;
          }
        }
        return intOf(big(l) + big(r));
      case "-":
        if (small) {
          const s = (l as number) - (r as number);
          if (Number.isSafeInteger(s)) {
            return s + 0;
          }
        }
        return intOf(big(l) - big(r));
      case "*":
        if (small) {
          const s = (l as number) * (r as number);
          if (Number.isSafeInteger(s)) {
            return s + 0;
          }
        }
        return intOf(big(l) * big(r));
      case "/":
      case "%":
        if (r === 0) {
          return evalError("division by zero");
        }
        if (small) {
          // Exact for safe integers; + 0 turns -0 into 0.
          return (op === "/" ? Math.trunc((l as number) / (r as number)) : (l as number) % (r as number)) + 0;
        }
        return intOf(op === "/" ? big(l) / big(r) : big(l) % big(r));
      case "<":
        return l < r;
      case "<=":
        return l <= r;
      case ">":
        return l > r;
      case ">=":
        return l >= r;
    }
  } else if (typeof l === "string" && typeof r === "string") {
    switch (op) {
      case "+":
        return l + r;
      case "<":
        return compareStrings(l, r) < 0;
      case "<=":
        return compareStrings(l, r) <= 0;
      case ">":
        return compareStrings(l, r) > 0;
      case ">=":
        return compareStrings(l, r) >= 0;
    }
  }
  return invalidOperands(op, l, r);
}

// --- OperatorsRule expressions ---

export interface OperatorsRule {
  skip: Matcher | null;
  operands: OperatorsRuleLine[];
  prefix: OperatorsRuleOp[];
  led: OperatorsRuleOp[];
}

export interface OperatorsRuleLine {
  scope: string[];
  m: Matcher;
  action: Action | null;
  // value makes the value of an operand line without an action, and of an operator line's
  // operator, from the value of the line's expression.
  value: Shaper;
}

export interface OperatorsRuleOp {
  id: number;
  kind: string;
  assoc: string;
  level: number;
  line: OperatorsRuleLine;
}

export interface OperatorsRuleAttempt {
  op: OperatorsRuleOp;
  frame: Frame;
  v: Node | null;
  start: number;
  end: number;
  env: Env | null;
  cut: boolean;
  errs: SyntaxError[];
}

// Declarations that the code generated for a grammar may not use, read here so that projects
// compiling with noUnusedLocals accept the module.
void [idBeginInput, idBeginLine, idEndLine, rtFold, rtUnary, rtAnd, rtOr, rtBinary];
